// Üretilen dosya: tool/ozgun/uret.py. Matematik ve Geometri · Üçgenlerde açı, kenar-açı bağıntıları, eşlik-benzerlik ve üçgenin yardımcı elemanları-merkezleri (ağırlık, iç-dış teğet, diklik, çevrel merkez) (orta).
const ozMathematics15Orta = <(String, String, List<String>, String)>[
  ('Kartondan kesilmiş ABC üçgeninde A köşesi, [AC] üzerindeki E ve [AB] üzerindeki F noktalarından geçen [EF] doğrusu boyunca katlandığında üçgenin iç bölgesindeki A\' noktasına geliyor. m(BAC) = 54° olduğuna göre m(BFE) + m(CEF) toplamı kaçtır?', '234°', ['216°', '252°', '288°'], 'AEF üçgeninde m(AEF) + m(AFE) = 180° - 54° = 126° olur. Bütünler açılar toplamı m(BFE) + m(CEF) = 360° - 126° = 234° bulunur.'),
  ('Masaya serilen KLM üçgeni biçimindeki kağıtta K köşesi, [KM] üzerindeki P noktasından geçen [LP] boyunca katlandığında [LM] kenarı üzerindeki K\' noktasıyla çakışıyor. m(PK\'M) = 112° ve m(M) = 30° ölçüldüğüne göre katlama öncesi KLP açısı kaç derecedir?', '41°', ['38°', '44°', '49°'], 'Doğrusallıktan m(LK\'P) = 180° - 112° = 68° ve katlama eşliğinden m(K) = 68° olur. Büyük üçgende m(L) = 180° - (68° + 30°) = 82° olup [LP] açıortay olduğundan m(KLP) = 82° / 2 = 41° bulunur.'),
  ('Bir üçgende iki iç açıortayın kesişmesiyle oluşan geniş açının ölçüsü, üçüncü köşedeki iç açının ölçüsünün üç katına eşittir. Üçüncü köşedeki iç açı kaç derecedir?', '36°', ['30°', '40°', '45°'], 'Üçüncü köşe açısı x ise diğer iki köşenin iç açıortayları arasındaki açı 90° + x/2 formülüyle bulunur. 90 + x/2 = 3x eşitliğinden 5x/2 = 90 ve x = 36° elde edilir.'),
  ('PRS üçgeninin R ve S köşelerine ait dış açıortaylar üçgenin dış bölgesindeki T noktasında kesişmektedir. m(RTS) = 53° olduğuna göre P köşesinin iç açısı kaç derecedir?', '74 derece', ['64 derece', '77 derece', '86 derece'], 'R ve S köşelerinin dış açıortayları arasındaki açı m(RTS) = 90° - m(P)/2 bağıntısını sağlar. 53 = 90 - m(P)/2 eşitliğinden m(P) = 74 derece bulunur.'),
  ('Herhangi bir DEF üçgeninde E köşesinin iç açıortayı ile F köşesinin dış açıortayı K noktasında kesişiyor. m(EKF) = 29° ise m(EDF) açısının ölçüsü nedir?', '58 derece', ['48 derece', '61 derece', '68 derece'], 'Bir iç açıortay ile farklı bir köşenin dış açıortayı arasındaki dar açı, üçüncü köşedeki iç açının yarısına eşittir; m(EDF) = 2 · 29° = 58 derecedir.'),
  ('Beş köşeli yıldız biçimindeki kapalı bir geometrik şeklin (pentagram) en uçtaki beş sivri köşesinde yer alan dar açıların ölçüleri toplamı kaç derecedir?', '180°', ['270°', '360°', '540°'], 'Beş köşeli yıldızda dış açı teoremi ardışık uygulandığında beş uç köşedeki dar açıların toplamı tek bir üçgenin iç açıları toplamına indirgenir ve daima 180° olur.'),
  ('Tepe noktası A olan ikizkenar bir ABC üçgeninde |AB| = |AC| olup [AC] kenarı üzerinde |AD| = |BD| = |BC| koşulunu sağlayan bir D noktası işaretleniyor. Buna göre m(BAC) açısı kaç derecedir?', '36 derece', ['30 derece', '32 derece', '40 derece'], 'm(BAC) = α denirse |AD| = |BD| olduğundan m(ABD) = α ve dış açıdan m(BDC) = 2α olur. |BD| = |BC| olduğundan m(C) = 2α ve m(ABC) = 2α bulunur; 5α = 180° denkleminden α = 36 derece çıkar.'),
  ('Saat yönünün tersine A köşesi etrafında 40° döndürülen bir ABC üçgeni AB\'C\' konumuna geliyor. Döndürme sonrasında B\' noktası ilk üçgenin [BC] kenarının üzerinde yer aldığına göre ilk üçgendeki ABC açısı kaç derecedir?', '70 derece', ['65 derece', '75 derece', '80 derece'], 'Döndürme uzunluğu koruduğundan |AB| = |AB\'| olur ve ABB\' ikizkenar üçgeninin tepe açısı 40 derecedir. Taban açısı m(ABB\') = (180 - 40) / 2 = 70 derece olup m(ABC) = 70 derecedir.'),
  ('Düzlem aynaya gelen bir lazer ışını, ayna yüzeyi ile 34 derecelik açı yaparak yansıyor ve birinci aynayla aralarında 78 derece açı bulunan ikinci düzlem aynaya çarpıyor. İkinci aynadan yansıyan ışının ikinci ayna yüzeyiyle yaptığı dar açı kaç derecedir?', '68 derece', ['56 derece', '62 derece', '74 derece'], 'Birinci aynadan yansıma açısı yüzeye göre 34° olup iki aynanın kesişim üçgeninde diğer köşe 78° olduğundan ışının ikinci aynayla yaptığı dar açı 180° - (34° + 78°) = 68° olur.'),
  ('Eşkenar bir KLM üçgeninin dış bölgesinde, M tarafında alınan P noktası için |KL| = |KP| ve m(PKL) = 84° eşitlikleri geçerlidir. Buna göre m(KMP) açısının ölçüsü kaç derecedir?', '78°', ['72°', '76°', '82°'], 'KLM eşkenar olduğundan |KL| = |KM| = |KP| olur. m(PKM) = 84° - 60° = 24° olan ikizkenar KPM üçgeninde taban açısı m(KMP) = (180° - 24°) / 2 = 78° elde edilir.'),
  ('Dış açılarının ölçüleri 4, 5 ve 6 sayılarıyla doğru orantılı olan çeşitkenar bir üçgenin en küçük iç açısının radyan türünden karşılığı nedir?', 'π/5 radyan', ['π/6 radyan', 'π/4 radyan', '2π/9 radyan'], 'Dış açılar 4k + 5k + 6k = 360° => k = 24° olup en büyük dış açı 144° ve en küçük iç açı 36° olur; 36° = 36π/180 = π/5 radyandır.'),
  ('Çeşitkenar bir ABC üçgeninde A köşesinden çizilen iç açıortay [BC] kenarını N noktasında, yükseklik ise H noktasında kesmektedir. m(ABC) = 76° ve m(ACB) = 34° olduğuna göre yükseklik ile açıortay arasındaki m(HAN) açısı kaçtır?', '21°', ['18°', '23°', '42°'], 'Bir köşeden çizilen yükseklik ile iç açıortay arasındaki dar açı, diğer iki köşe açısının farkının mutlak değerinin yarısıdır: |76° - 34°| / 2 = 21°.'),
  ('Dar açılı bir üçgende tüm iç açıların ölçüleri birbirinden farklı birer tam sayıdır ve en büyük iç açı 62 derecedir. Bu üçgenin en küçük iç açısı en az kaç derece olabilir?', '57 derece', ['56 derece', '58 derece', '59 derece'], 'En büyük açı 62° olduğundan ortanca açı en fazla 61° seçilebilir. İç açılar toplamı 180° olduğu için en küçük açı en az 180° - (62° + 61°) = 57 derece olur.'),
  ('Geniş açılı bir ikizkenar üçgenin iç açılarının derece cinsinden ölçüleri birer tam sayıdır. Eş olan dar açılardan birinin alabileceği en büyük tam sayı değeri kaçtır?', '44°', ['43°', '45°', '89°'], 'Tepe açısı 90 dereceden büyüktür; taban açılarının tam sayı olması için tepe açısı çift tam sayı seçilmelidir. Tepe açısı en az 92° alındığında taban açıları en çok (180° - 92°) / 2 = 44° olur.'),
  ('İç açılarının tamamı derece cinsinden tam sayı olan geniş açılı çeşitkenar bir üçgende, geniş açının alabileceği en küçük değer ile en küçük dar açının alabileceği en küçük değerin toplamı kaçtır?', '92°', ['91°', '93°', '94°'], 'Geniş açının en küçük tam sayı değeri 91° (örneğin 1°, 88°, 91° üçgeni), en küçük dar açının alabileceği en küçük tam sayı değeri ise 1° olduğundan toplamları 92° olur.'),
  ('Tepe noktası A olan ikizkenar bir ABC üçgeninde |AB| = |AC| olup [BA ışını üzerinde A noktasından ötede |AD| = |AC| olacak biçimde bir D noktası işaretleniyor. Buna göre m(BCD) açısının ölçüsü kaç derecedir?', '90°', ['75°', '80°', '105°'], '|AB| = |AC| = |AD| eşitliği A merkezli çember üzerinde B, C ve D noktalarının bulunduğunu ve [BD]\'nin çap olduğunu gösterir; çapı gören çevre açı (muhteşem üçlünün tersi) gereği m(BCD) = 90° olur.'),
  ('Düzgün beşgen şeklindeki bir levhanın bir köşesinden çizilen iki köşegen, beşgeni üç adet üçgene ayırmaktadır. Ortada oluşan dar tepe açılı ikizkenar üçgenin taban açılarından birinin ölçüsü kaçtır?', '72°', ['54°', '60°', '68°'], 'Düzgün beşgenin bir iç açısı 108° olup bir köşeden çizilen iki köşegen bu açıyı üç eş parçaya (36°, 36°, 36°) böler. Ortadaki ikizkenar üçgenin tepe açısı 36° olduğundan taban açısı (180° - 36°) / 2 = 72° olur.'),
  ('Denizdeki bir tekne limandan kuzeyle doğu yönünde 35° açı yaparak doğrusal ilerliyor, şamandıraya vardığında rotasını tam güneydoğu (güney ile doğu arası 45°) yönüne çeviriyor. Şamandıra noktasında teknenin ilk geliş doğrultusu ile yeni gidiş doğrultusu arasındaki iç dönüş açısı (üçgenin şamandıra köşesindeki iç açısı) kaç derecedir?', '80°', ['70°', '85°', '100°'], 'Şamandıradan geçen kuzey-güney doğrusu çizildiğinde geliş kolu güney yönüyle iç ters açıdan 35°, gidiş kolu ise güney yönüyle doğuya doğru 45° açı yapar; aralarındaki açı 35° + 45° = 80° olur.'),
  ('m(B) = 90° ve m(C) = 25° olan bir ABC dik üçgeninde C köşesi, [AC] üzerindeki E ve [BC] üzerindeki D noktalarından geçen doğru boyunca katlandığında B köşesiyle çakışıyor. Buna göre m(ABE) açısının ölçüsü kaç derecedir?', '65°', ['50°', '55°', '75°'], 'C köşesi B ile çakıştığından katlama izi [BC]\'nin orta dikmesidir ve |BE| = |EC| olur. BEC ikizkenar üçgeninde m(EBC) = 25° olup m(ABE) = 90° - 25° = 65° bulunur.'),
  ('Dikdörtgen biçimindeki uzun bir şerit kağıt bir kez katlandığında üst üste binen bölgede bir üçgen meydana geliyor. Bu kesişim üçgeninin kenarlarına göre türü her zaman aşağıdakilerden hangisidir?', 'İkizkenar üçgen', ['Çeşitkenar üçgen', 'Eşkenar üçgen', 'Dik açılı üçgen'], 'Şeridin paralel kenarlarından dolayı iç ters açılar eşit, katlama simetrisinden dolayı katlama açıları eşit olur; böylece iki taban açısı eşit olan bir ikizkenar üçgen oluşur.'),
  ('Paralel kenarlı bir şerit kağıt, katlama izi şeridin uzun kenarıyla 52° dar açı yapacak biçimde katlanıyor. Kağıdın katlanan kolu ile sabit kalan kolunun uzun kenarları arasında oluşan dar açı kaç derecedir?', '76°', ['64°', '72°', '78°'], 'Katlama izinin uzun kenarla yaptığı dar açı 52° ise katlanan parça da izle 52° açı yapar; toplam 104° olur. Uzun kenarın doğrultusuyla (180° tamamlayanı) yapılan dar açı 180° - 104° = 76° bulunur.'),
  ('Bir üçgende B ve C köşelerindeki dış açıortayların kesim noktası K, iç açıortayların kesim noktası ise I olarak adlandırılıyor. m(BKC) = 64° olduğuna göre m(BIC) açısının ölçüsü kaç derecedir?', '116°', ['106°', '114°', '126°'], 'IBKC dörtgeninde B ve C köşelerinde iç ve dış açıortaylar birbirine dik olduğundan m(IBK) = m(ICK) = 90° olur. Dolayısıyla m(BIC) + m(BKC) = 180° olup m(BIC) = 180° - 64° = 116° bulunur.'),
  ('Aynı düzlemdeki ABC ve BDC üçgenlerinde [BC] kenarı ortaktır; I noktası ABC\'nin iç açıortaylarının kesim noktası, D noktası ise B ve C dış açıortaylarının kesim noktasıdır. IBDC dörtgeninin karşılıklı B ve C köşelerindeki tam açıların toplamı kaç derecedir?', '180 derece', ['90 derece', '120 derece', '270 derece'], 'Komşu bütünler iki açının açıortayları arasındaki açı 90° olduğundan m(IBD) = 90° ve m(ICD) = 90° olur; toplamları 180 derecedir.'),
  ('Bir pergelin eşit uzunluktaki iki kolu arasındaki açı 46° olacak biçimde açılıp uçları düz bir kağıda batırılıyor. Ardından pergelin kolları arasındaki açı 18° daha genişletilerek aynı kağıda tekrar batırılırsa oluşan yeni ikizkenar üçgenin taban açısı ilk duruma göre nasıl değişir?', '9 derece azalır', ['9 derece artar', '18 derece azalır', '18 derece artar'], 'Tepe açısı 46° iken taban açısı (180° - 46°)/2 = 67°; tepe açısı 64° olduğunda taban açısı (180° - 64°)/2 = 58° olur ve 9 derece azalır.'),
  ('Eşkenar bir ABC üçgeninin iç bölgesinde seçilen P noktasından üç kenara paralel doğrular çiziliyor; bu paralellerin kenarlarla oluşturduğu dar ve geniş açılar incelendiğinde P noktasında oluşan altı komşu açıdan her birinin ölçüsü kaç derecedir?', '60°', ['30°', '45°', '75°'], 'Eşkenar üçgenin kenarları birbirleriyle 60° açı yaptığından kenarlara paralel çizilen üç doğru P noktasında birbirini 60 derecelik altı eş açıyla keser.'),
  ('Bir ABC üçgeninde [AC] kenarı üzerinde alınan D noktası için |AB| = |BD| = |DC| eşitlikleri sağlanıyor. m(ACB) = 27° olduğuna göre m(ABC) açısının tamamı kaç derecedir?', '99°', ['93°', '102°', '108°'], '|BD| = |DC| olduğundan m(DBC) = 27° ve dış açıdan m(ADB) = 54° olur. |AB| = |BD| ise m(BAD) = 54° ve m(ABD) = 72° bulunur; dolayısıyla m(ABC) = 72° + 27° = 99° elde edilir.'),
  ('Ölçüleri 42° 18\' ve 57° 52\' olan iki iç açıya sahip bir üçgenin üçüncü iç açısının derece ve dakika cinsinden değeri nedir?', '79° 50\'', ['79° 10\'', '80° 10\'', '80° 50\''], 'Verilen iki açının toplamı 99° 70\' = 100° 10\' yapar. 180° = 179° 60\' değerinden 100° 10\' çıkarıldığında 79° 50\' bulunur.'),
  ('Bir ABC üçgeni B köşesi etrafında saat yönünde 60° döndürüldüğünde A noktası A\' konumuna geliyor. A ile A\' noktaları birleştirildiğinde elde edilen ABA\' üçgeninin türü aşağıdakilerden hangisidir?', 'Eşkenar üçgen', ['İkizkenar dik üçgen', 'Geniş açılı ikizkenar üçgen', 'Çeşitkenar dar üçgen'], 'Döndürmede |BA| = |BA\'| korunduğundan ve aralarındaki döndürme açısı m(ABA\') = 60° olduğundan tepe açısı 60° olan ikizkenar üçgen eşkenar üçgene dönüşür.'),
  ('Düzgün dokuzgen biçimindeki bir çerçevede ardışık K, L ve M köşeleri birleştirilerek KLM üçgeni oluşturuluyor. Bu üçgenin dar açılarından birinin ölçüsü kaç derecedir?', '20°', ['15°', '18°', '24°'], 'Düzgün dokuzgenin bir dış açısı 360° / 9 = 40°, bir iç açısı 140° olur. |KL| = |LM| olduğundan taban açısı (180° - 140°) / 2 = 20° bulunur.'),
  ('Tepe açısı m(A) = 100° olan ikizkenar bir ABC üçgeninde (|AB| = |AC|), [BC] kenarı üzerinde |BD| = |BA| koşulunu sağlayan D noktası alınıyor. Buna göre m(DAC) açısının ölçüsü kaçtır?', '30°', ['20°', '25°', '35°'], 'ABC üçgeninde m(B) = m(C) = (180° - 100°)/2 = 40° olur. |BD| = |BA| olduğundan ABD ikizkenar üçgeninde m(BAD) = (180° - 40°)/2 = 70° ve buradan m(DAC) = 100° - 70° = 30° bulunur.'),
  ('Bir üçgende üç dış açının ikisi dar açı olabilir mi sorusunu inceleyen bir öğrenci aşağıdaki yargılardan hangisine ulaşırsa matematiksel olarak doğru çıkarım yapmış olur?', 'En fazla bir dış açı dar açı olabilir', ['İki dış açı da dar açı seçilebilir', 'Üç dış açı da dar açı olabilir', 'Hiçbir dış açı dar açı olamaz'], 'Bir dış açının dar olması komşu iç açının geniş (>90°) olmasını gerektirir; bir üçgende en çok bir geniş iç açı bulunabileceğinden en fazla bir dış açı dar olabilir.'),
  ('Dar açılı bir PRS üçgeninde m(P) = 52° olup R köşesinden [PS] kenarına indirilen yükseklik ile S köşesinden [PR] kenarına indirilen yükseklik H noktasında kesişmektedir. Buna göre m(RHS) geniş açısı kaç derecedir?', '128°', ['116°', '124°', '138°'], 'Yükseklik ayakları D ve E denirse PDHE dörtgeninde iki karşılıklı açı 90° olduğundan m(DHE) = 180° - 52° = 128° ve ters açılardan m(RHS) = 128° bulunur.'),
  ('Bir üçgenin iç açıları aritmetik dizi oluşturmaktadır (ardışık terimler arasındaki fark sabittir). Bu üçgenin ortanca büyüklükteki iç açısının ölçüsü her zaman kaç derecedir?', '60 derece', ['45 derece', '50 derece', '75 derece'], 'Aritmetik dizideki üç açı x - d, x ve x + d biçiminde yazıldığında toplamları 3x = 180° verir; buradan ortanca açı x = 60 derece olarak sabit kalır.'),
  ('İç açıları geometrik değil aritmetik dizi oluşturan bir dik üçgenin en küçük dar açısının radyan cinsinden değeri aşağıdakilerden hangisidir?', 'π/6 radyan', ['π/12 radyan', 'π/4 radyan', 'π/3 radyan'], 'Aritmetik dizi oluşturan üçgenin ortanca açısı 60° ve dik üçgen olduğu için en büyük açısı 90° olduğundan en küçük dar açısı 30° = π/6 radyandır.'),
  ('Bir ABC üçgeninde A köşesinden [BC] tabanına paralel çizilen bir ışın, A köşesindeki dış açıyı 43° ve 59° ölçülerinde iki komşu açıya ayırıyor. Buna göre üçgenin en büyük iç açısı kaç derecedir?', '78°', ['68°', '74°', '82°'], 'A dış açısının tamamı 43° + 59° = 102° olduğundan m(BAC) = 180° - 102° = 78° olur; paralel ışın sayesinde diğer iki iç açı iç ters ve yöndeşlikten 43° ve 59° olduğundan en büyük iç açı 78° bulunur.'),
  ('Dar açılı bir ABC üçgeninde B ve C köşelerinden karşı kenarlara indirilen yükseklikler H noktasında kesişiyor. Yüksekliklerin oluşturduğu m(BHC) geniş açısı 136° ise|AB| = |AC| ikizkenarlık koşulu altında taban açılarından biri kaç derecedir?', '68°', ['62°', '66°', '72°'], 'Yükseklik ayaklarıyla oluşan dörtgende m(A) + 136° = 180° eşitliğinden tepe açısı m(A) = 44° bulunur. İkizkenar üçgenin taban açısı (180° - 44°) / 2 = 68° olur.'),
  ('m(BAC) = 90° olan bir ABC dik üçgeninde A köşesinin iç açıortayı hipotenüsü D noktasında kesmektedir. m(ADB) = 103° olduğuna göre C köşesindeki dar açının ölçüsü kaçtır?', '58°', ['47°', '52°', '63°'], 'Dik açının açıortayı m(DAC) = 45° oluşturur. ADC üçgeninde dış açı özelliğinden m(ADB) = m(DAC) + m(C) => 103° = 45° + m(C) => m(C) = 58° bulunur.'),
  ('ABC üçgeninde A köşesindeki dış açının ölçüsü, B köşesindeki iç açının ölçüsünün 5/3 katına eşittir. Buna göre C iç açısının B iç açısına oranı kaçtır?', '2/3', ['1/3', '3/5', '3/2'], 'Dış açı teoreminden m(B) + m(C) = (5/3)·m(B) yazılır; buradan m(C) = (2/3)·m(B) ve m(C)/m(B) = 2/3 oranı elde edilir.'),
  ('m(L) = 90° olan bir KLM dik üçgeninde [KM] hipotenüsünün orta noktası O olarak işaretleniyor. |KL| = |LO| eşitliği sağlandığına göre m(LOM) geniş açısı kaç derecedir?', '120°', ['105°', '115°', '135°'], 'Muhteşem üçlüden |KO| = |LO| = |OM| olup |KL| = |LO| verildiğinden KLO üçgeni eşkenardır ve m(KOL) = 60° olur. Bütünler açı olan m(LOM) = 180° - 60° = 120° bulunur.'),
  ('Düzgün onikigen şeklindeki bir saat kadranının merkezini ardışık iki köşeye birleştiren doğru parçaları ile kenarın oluşturduğu ikizkenar üçgenin taban açısı kaç derecedir?', '75°', ['70°', '72°', '78°'], 'Düzgün onikigenin merkez açısı 360° / 12 = 30° olup yarıçaplarla oluşan ikizkenar üçgenin taban açısı (180° - 30°) / 2 = 75° olur.'),
  ('|AB| = |BC| olan ikizkenar bir ABC üçgeninde [AC] tabanı C yönünde doğrusal uzatılarak |CD| = |BC| koşulunu sağlayan bir D noktası alınıyor. m(BDA) = 23° olduğuna göre m(ABC) tepe açısı kaç derecedir?', '88°', ['84°', '92°', '96°'], '|BC| = |CD| ikizkenarlığından m(CBD) = 23° ve dış açı m(ACB) = 46° olur. |AB| = |BC| olduğundan m(A) = 46° ve m(ABC) = 180° - 92° = 88° elde edilir.'),
  ('Paralel d1 ve d2 doğruları arasına çizilen bir eşkenar üçgenin bir köşesi d1 üzerinde, ikinci köşesi d2 üzerinde, üçüncü köşesi ise iki doğrunun arasındaki bölgede yer almaktadır. Üçgenin bir kenarı d1 doğrusuyla 17° dar açı yaptığına göre diğer kenarının d2 doğrusuyla yaptığı dar açı kaçtır?', '43°', ['37°', '47°', '53°'], 'Paralel doğrular arasındaki M kuralına göre eşkenar üçgenin aradaki 60 derecelik köşe açısı 17° + x toplamına eşittir; buradan x = 60° - 17° = 43° bulunur.'),
  ('DEF üçgeninde [DE] kenarının orta dikme doğrusu [DF] kenarını K noktasında kesmektedir. m(EKF) = 74° olduğuna göre m(EDF) açısının ölçüsü kaç derecedir?', '37°', ['32°', '36°', '42°'], 'Kenar orta dikme üzerindeki K noktası uçlara eşit uzaklıktadır (|KD| = |KE|). DKE ikizkenar üçgeninde m(KDE) = m(DEK) olup dış açı 74° = 2·m(EDF) eşitliğinden m(EDF) = 37° bulunur.'),
  ('Kenar uzunlukları a, b ve c birim olan herhangi bir üçgende |a - b - c| + |b + c - a| mutlak değerli ifadesinin en sade biçimi aşağıdakilerden hangisidir?', '2b + 2c - 2a', ['2a', '0', '2b - 2c'], 'Üçgen eşitsizliğinden a < b + c olduğu için a - b - c < 0 ve b + c - a > 0 olur. Mutlak değerden -(a - b - c) + (b + c - a) = 2b + 2c - 2a olarak çıkar.'),
  ('Çeşitkenar bir ABC üçgeninde |AB| = 6 birim ve |AC| = 10 birimdir. |BC| kenarının birim cinsinden alabileceği kaç farklı tam sayı değeri vardır?', '9 farklı değer', ['10 farklı değer', '11 farklı değer', '8 farklı değer'], 'Üçgen eşitsizliğinden 4 < |BC| < 16 bulunur ve bu aralıkta 11 tam sayı vardır. Üçgen çeşitkenar olduğundan 6 ve 10 değerleri elenir; geriye 9 farklı değer kalır.'),
  ('[BD] köşegeni ortak olan dışbükey bir ABCD dörtgeninde |AB| = 4 cm, |AD| = 8 cm, |BC| = 6 cm ve |CD| = 12 cm olarak veriliyor. |BD| köşegeninin alabileceği tam sayı değerlerinin toplamı kaç santimetredir?', '45 cm', ['38 cm', '51 cm', '57 cm'], 'ABD üçgeninde 4 < |BD| < 12, BCD üçgeninde ise 6 < |BD| < 18 eşitsizlikleri elde edilir. Kesişim aralığı 6 < |BD| < 12 olup tam sayılar 7, 8, 9, 10 ve 11\'dir; toplamları 45 cm eder.'),
  ('m(BAC) > 90° olan geniş açılı bir ABC üçgeninde |AB| = 8 birim ve |AC| = 15 birimdir. |BC| kenarının birim cinsinden alabileceği en küçük tam sayı değeri kaçtır?', '18 birim', ['16 birim', '17 birim', '19 birim'], 'A açısı 90° olsaydı 8-15-17 üçgeni oluşurdu; m(A) > 90° olduğundan |BC|² > 8² + 15² = 289 yani |BC| > 17 olur. Üst sınır 8 + 15 = 23 olduğundan en küçük tam sayı 18 birimdir.'),
  ('Yalnızca A köşesindeki iç açısının dar açı olduğu (m(A) < 90°) bilinen bir ABC üçgeninde |AB| = 9 cm ve |AC| = 12 cm ise |BC| kenarı en fazla kaç santimetre tam sayı değer alabilir?', '14 cm', ['13 cm', '15 cm', '20 cm'], 'm(A) < 90° koşulundan |BC|² < 9² + 12² = 225 yani |BC| < 15 elde edilir; alt sınır |12 - 9| = 3 olduğundan en büyük tam sayı 14 cm olur.'),
  ('Çevre uzunluğu 31 metre olan üçgen biçimindeki bir bahçenin bir kenarının uzunluğu tam sayı olarak en fazla kaç metre olabilir?', '15 metre', ['14 metre', '16 metre', '17 metre'], 'Üçgen eşitsizliğinden herhangi bir kenar diğer iki kenarın toplamından küçüktür; a < b + c her iki tarafa a eklenirse 2a < 31 => a < 15,5 bulunur ve en büyük tam sayı 15 metredir.'),
  ('Kenar uzunlukları santimetre cinsinden birer tam sayı ve çevresi 18 cm olan, eşkenar üçgen dışındaki farklı ikizkenar üçgenlerin sayısı kaçtır?', '3 tane', ['2 tane', '4 tane', '5 tane'], 'Eş kenarlar a ve taban b için 2a + b = 18 ve b < 2a => b < 9 olur. Çift olan b değerleri 2, 4, 6, 8 olup (8,8,2), (7,7,4), (6,6,6) ve (5,5,8) elde edilir; eşkenar olan (6,6,6) çıkarılınca 3 tane kalır.'),
  ('Kenar uzunlukları |AB| = 7 birim, |BC| = 11 birim ve |AC| = 10 birim olan ABC üçgeninin iç bölgesinde bir P noktası seçiliyor. |PA| + |PB| + |PC| toplamının alabileceği en küçük tam sayı değeri kaçtır?', '15 birim', ['14 birim', '16 birim', '27 birim'], 'Üçgenin iç bölgesindeki bir noktanın köşelere uzaklıkları toplamı yarı çevre ile çevre arasındadır: 28/2 < toplam < 28 => 14 < toplam < 28 olduğundan en küçük tam sayı 15 birimdir.'),
  ('|AB| = 8 cm, |AC| = 11 cm ve |BC| = 9 cm olan ABC üçgeninin iç bölgesinde alınan bir P noktası için |PB| + |PC| toplamının santimetre cinsinden alabileceği en büyük tam sayı değeri nedir?', '18 cm', ['17 cm', '19 cm', '20 cm'], 'İç bölgedeki nokta için zarf eşitsizliği gereği |BC| < |PB| + |PC| < |AB| + |AC| geçerlidir; 9 < |PB| + |PC| < 19 aralığından en büyük tam sayı 18 cm bulunur.'),
  ('Düzlemde [AC] kenarı ortak olan bitişik ABC ve ACD üçgenleri çiziliyor. ABC üçgeninde m(A) = 65° ve m(B) = 55°; ACD üçgeninde ise m(DAC) = 50° ve m(ADC) = 70° olduğuna göre şeklin en kısa doğru parçası hangisidir?', '[CD] kenarı', ['[AD] kenarı', '[AC] köşegeni', '[AB] kenarı'], 'ABC\'de m(C) = 60° olup açı-kenar sırasından |AC| < |AB| < |BC| bulunur. ACD\'de m(ACD) = 60° olup |CD| < |AD| < |AC| elde edilir. İkisi birleştiğinde en kısa parça [CD] kenarıdır.'),
  ('Boyları 3 cm, 5 cm, 7 cm, 9 cm ve 11 cm olan beş doğrusal çubuk arasından rastgele üç tanesi seçilerek uç uca eklendiğinde kaç farklı üçgen oluşturulabilir?', '7 farklı üçgen', ['6 farklı üçgen', '8 farklı üçgen', '9 farklı üçgen'], '10 olası üçlüden yalnızca (3,5,9), (3,5,11) ve (3,7,11) üçlüleri a + b > c koşulunu sağlamaz; kalan 7 üçlü üçgen eşitsizliğini sağlar.'),
  ('Bir üçgenin üç kenarına ait yükseklik uzunlukları arasında ha < hb < hc sıralaması bulunduğuna göre üçgenin iç açılarının doğru sıralanışı hangisidir?', 'm(A) > m(B) > m(C)', ['m(A) < m(B) < m(C)', 'm(B) > m(A) > m(C)', 'm(C) > m(A) > m(B)'], 'Üçgende alan a·ha/2 = b·hb/2 = c·hc/2 olduğundan yükseklikler kenarlarla ters orantılıdır. ha < hb < hc ise a > b > c olur ve büyük kenarı gören açı büyüktür: m(A) > m(B) > m(C).'),
  ('İkizkenar bir ABC üçgeninde |AB| = |AC| olup [BC] tabanının C yönündeki uzantısı üzerinde bir D noktası alınıyor. |AB| ile |AD| uzunlukları karşılaştırıldığında hangi bağıntı daima doğrudur?', '|AD| > |AB|', ['|AD| < |AB|', '|AD| = |AB|', '|AD| ≤ |AB|'], 'İkizkenar üçgende taban açısı m(ACB) dar açı olduğundan bütünleri m(ACD) geniş açıdır (>90°). Geniş açılı ACD üçgeninde geniş açıyı gören |AD| en uzun kenardır: |AD| > |AC| = |AB|.'),
  ('Uzunluğu 24 cm olan düz bir tel, uçları birleşecek biçimde iki noktadan bükülerek kenar uzunlukları santimetre cinsinden tam sayı olan bir eşkenar olmayan çeşitkenar üçgen haline getiriliyor. En kısa kenarın uzunluğu en fazla kaç santimetre olabilir?', '7 cm', ['6 cm', '8 cm', '9 cm'], 'Çeşitkenar üçgende kenarlar a < b < c tam sayıları ve a + b + c = 24 olmalıdır. a = 8 alınırsa en az 8 + 9 + 10 = 27 > 24 olur; a = 7 alındığında 7 + 8 + 9 = 24 üçgen eşitsizliğini (7 + 8 > 9) sağlar.'),
  ('Kenar uzunlukları 7 birim, 8 birim ve 9 birim olan bir üçgenin en büyük iç açısı hakkında aşağıdakilerden hangisi kesinlikle doğrudur?', '60° ile 90° arasında bir dar açıdır', ['90 derecelik bir dik açıdır', '90° ile 120° arasında geniş açıdır', '45° ile 60° arasında bir dar açıdır'], 'En büyük kenar 9 olduğundan en büyük açı 60 dereceden büyüktür (çeşitkenar üçgende en büyük açı > 60°). Ayrıca 9² = 81 < 7² + 8² = 113 olduğundan bu açı 90 dereceden küçüktür.'),
  ('İkizkenar bir üçgenin farklı iki kenarının uzunluğu 6 birim ve 10 birimdir. Bu üçgenin çevresinin alabileceği farklı değerlerin toplamı kaç birimdir?', '48 birim', ['22 birim', '26 birim', '44 birim'], '(6, 6, 10) üçlüsünde 6 + 6 > 10 sağlandığından çevre 22 birim olabilir; (10, 10, 6) üçlüsünde de 10 + 6 > 10 sağlandığından çevre 26 birim olabilir. Toplamları 22 + 26 = 48 birimdir.'),
  ('DEF üçgeninde [DE] ve [DF] kenarlarının orta noktaları sırasıyla K ve L\'dir. |DE| = 6 cm ve |DF| = 14 cm olduğuna göre [KL] orta tabanının santimetre cinsinden alabileceği tam sayı değerleri hangileridir?', '5, 6, 7, 8 ve 9', ['4, 5, 6, 7, 8 ve 9', '5, 6, 7, 8, 9 ve 10', '6, 7, 8, 9, 10 ve 11'], 'Üçgen eşitsizliğinden 14 - 6 < |EF| < 14 + 6 yani 8 < |EF| < 20 bulunur. Orta taban |KL| = |EF|/2 olduğundan 4 < |KL| < 10 elde edilir; tam sayılar 5, 6, 7, 8 ve 9\'dur.'),
  ('Bir izci kamp noktasından önce tam doğuya 7 km, ardından tam kuzeye 11 km, son olarak tekrar tam doğuya 8 km yürüyerek gözetleme kulesine ulaşıyor. Kamp noktası ile kule arasındaki kuş uçuşu mesafe kaç kilometredir?', '√346 km', ['19 km', '√320 km', '26 km'], 'Toplam doğu yer değiştirmesi 7 + 8 = 15 km, kuzey yer değiştirmesi 11 km olur. Dik üçgende kuş uçuşu uzaklık √(15² + 11²) = √(225 + 121) = √346 km bulunur.'),
  ('Yüksekliği 16 metre ve yüksekliği 28 metre olan iki dikey kule arasındaki yatay zemin uzaklığı 35 metredir. İki kulenin en üst noktaları arasına gerilecek doğrusal kablonun uzunluğu kaç metredir?', '37 metre', ['36 metre', '39 metre', '41 metre'], 'Kulelerin yükseklik farkı 28 - 16 = 12 metre, yatay uzaklık 35 metredir. Oluşan dik üçgende kablo uzunluğu √(12² + 35²) = √(144 + 1225) = √1369 = 37 metredir.'),
  ('Fırtınada yerden 8 metre yükseklikten kırılan dik bir kavak ağacının üst gövdesi kırılma noktasından kopmadan devrilerek uç noktası ağacın kökünden 15 metre uzağa değiyor. Kırılmadan önce ağacın tam boyu kaç metreydi?', '25 metre', ['23 metre', '24 metre', '27 metre'], 'Dik kenarları 8 m ve 15 m olan dik üçgende devrilen üst kısmın uzunluğu hipotenüs olup √(8² + 15²) = 17 metredir. Ağacın ilk boyu 8 + 17 = 25 metre olur.'),
  ('Düşey bir duvara dayalı 25 dm uzunluğundaki merdivenin üst ucu yerden 24 dm yüksekliktedir. Merdivenin üst ucu duvardan aşağı doğru 4 dm kaydığında alt ucu duvardan kaç desimetre daha uzaklaşır?', '8 dm', ['4 dm', '6 dm', '15 dm'], 'İlk durumda alt ucun duvara uzaklığı √(25² - 24²) = 7 dm\'dir. Üst uç 4 dm kayınca yükseklik 20 dm olur; yeni yatay uzaklık √(25² - 20²) = 15 dm olduğundan alt uç 15 - 7 = 8 dm uzaklaşır.'),
  ('Köşegenleri birbirine dik kesişen dışbükey bir ABCD dörtgeninde |AB| = 5 birim, |CD| = 9 birim ve |BC| = 7 birim olduğuna göre |AD| kenarının uzunluğu kaç birimdir?', '√57 birim', ['√53 birim', '8 birim', '√65 birim'], 'Köşegenleri dik kesişen dörtgenlerde karşılıklı kenarların kareleri toplamı birbirine eşittir: |AB|² + |CD|² = |BC|² + |AD|² => 25 + 81 = 49 + |AD|² => |AD|² = 57 => |AD| = √57 birim bulunur.'),
  ('Kenar uzunlukları |AB| = 13 cm, |AC| = 15 cm ve |BC| = 14 cm olan bir ABC üçgeninde A köşesinden [BC] kenarına indirilen dikmenin [BC] üzerinde ayırdığı kısa parçanın uzunluğu kaç santimetredir?', '5 cm', ['4 cm', '6 cm', '9 cm'], 'Dikme ayağı H ve |BH| = x denirse |HC| = 14 - x olur. Ortak yükseklik h için 13² - x² = 15² - (14 - x)² => 169 - x² = 225 - 196 + 28x - x² => 28x = 140 => x = 5 cm (diğer parça 9 cm) bulunur.'),
  ('m(A) = 90° olan ABC dik üçgeninde [AH] ⊥ [BC] olup dik kenarların uzunlukları oranı |AB| / |AC| = 2 / 3 olarak veriliyor. Hipotenüs üzerindeki dik iz düşüm parçalarının oranı |BH| / |HC| kaçtır?', '4/9', ['2/3', '√2/√3', '8/27'], 'Öklid bağıntılarından |AB|² = |BH|·|BC| ve |AC|² = |HC|·|BC| yazıldığında oranları |BH| / |HC| = (|AB| / |AC|)² = (2/3)² = 4/9 verir.'),
  ('m(BAC) = 90° ve [AH] ⊥ [BC] olan bir ABC dik üçgeninde |AH| = 2√6 birim ve hipotenüs uzunluğu |BC| = 11 birim olduğuna göre dik kenarlardan kısa olanının uzunluğu kaç birimdir?', '√33 birim', ['5 birim', '2√7 birim', '6 birim'], '|BH| = p ve |HC| = k için p + k = 11 ve p · k = (2√6)² = 24 olur. Çarpımları 24, toplamları 11 olan sayılar 3 ve 8\'dir; kısa dik kenar √(3 · 11) = √33 birim bulunur.'),
  ('Bir ABC üçgeninde A köşesinden [BC] kenarının orta noktası olan D\'ye çizilen kenarortay için |AD| = |BD| = |DC| = 10 cm ve |AB| = 12 cm eşitlikleri sağlanmaktadır. Buna göre |AC| kenarı kaç santimetredir?', '16 cm', ['14 cm', '15 cm', '18 cm'], 'Kenarortay uzunluğu böldüğü parçaların her birine eşit olduğundan muhteşem üçlünün karşıtı gereği m(BAC) = 90° ve |BC| = 20 cm olur. 12-16-20 dik üçgeninden |AC| = 16 cm elde edilir.'),
  ('Bir ABC üçgeninde m(B) = 45°, m(C) = 30° ve |AB| = 8√2 cm olarak veriliyor. Buna göre |BC| tabanının toplam uzunluğu kaç santimetredir?', '8 + 8√3 cm', ['8 + 4√3 cm', '16 cm', '8√2 + 8√3 cm'], 'A köşesinden [BC]\'ye [AH] dikmesi indirildiğinde 45°-45°-90° üçgeninden |AH| = |BH| = 8 cm olur. Sağdaki 30°-60°-90° üçgeninde 30° karşısı 8 cm ise 60° karşısı |HC| = 8√3 cm olup |BC| = 8 + 8√3 cm bulunur.'),
  ('Geniş açılı bir KLM üçgeninde m(L) = 120°, |KL| = 6 birim ve |LM| = 10 birim olduğuna göre geniş açının karşısındaki |KM| kenarı kaç birimdir?', '14 birim', ['12 birim', '2√34 birim', '15 birim'], '[ML] doğrusu L yönünde uzatılıp K\'dan dikme indirildiğinde 60° dış açılı 30°-60°-90° dik üçgeni oluşur; dikme ayağı H için |LH| = 3 ve |KH| = 3√3 olur. KHM dik üçgeninde |KM| = √((3√3)² + (3 + 10)²) = √(27 + 169) = √196 = 14 birim bulunur.'),
  ('m(ABC) = 135°, |AB| = 5√2 cm ve |BC| = 12 cm olan bir ABC üçgeninde |AC| kenarının uzunluğu kaç santimetredir?', '√314 cm', ['17 cm', '√298 cm', '18 cm'], '[CB] kenarı B yönünde uzatılıp A\'dan dikme indirildiğinde bütünler açı 45° olur; |AB| = 5√2 cm olduğundan dikme yüksekliği 5 cm ve uzantı parçası 5 cm\'dir. Büyük dik üçgende |AC| = √(5² + (5 + 12)²) = √(25 + 289) = √314 cm elde edilir.'),
  ('Bir ABC üçgeninde m(A) = 75°, m(C) = 45° ve |AC| = 12 cm olduğuna göre |AB| kenarının uzunluğu kaç santimetredir?', '4√6 cm', ['6√2 cm', '6√3 cm', '8√2 cm'], 'm(B) = 180° - (75° + 45°) = 60° bulunur. A köşesinden [BC] kenarına [AH] dikmesi çizildiğinde 45°-45°-90° üçgeninden |AH| = 6√2 cm olur. ABH (30°-60°-90°) üçgeninde 60° karşısı 6√2 cm olduğundan hipotenüs |AB| = (6√2 / √3) · 2 = 4√6 cm elde edilir.'),
  ('|AB| = |AC| = 13 birim ve |BC| = 10 birim olan ikizkenar ABC üçgeninde B köşesinden [AC] yan kenarına indirilen yüksekliğin uzunluğu kaç birimdir?', '120/13 birim', ['10 birim', '108/13 birim', '12 birim'], 'Tepe noktasından [BC]\'ye inen yükseklik tabanı 5-5 böler ve 5-12-13 üçgeninden ha = 12 birim bulunur. Üçgenin alanı değişmeyeceğinden 10 · 12 / 2 = 13 · hb / 2 => hb = 120/13 birim elde edilir.'),
  ('|AB| = |AC| = 10 cm olan ikizkenar ABC üçgeninin [BC] tabanı üzerinde alınan bir D noktası için |BD| = 3 cm ve |DC| = 9 cm eşitlikleri geçerlidir. Buna göre |AD| doğru parçasının uzunluğu kaç santimetredir?', '√73 cm', ['8 cm', '√71 cm', '√79 cm'], 'A\'dan [BC] tabanına [AH] dikmesi indirildiğinde |BC| = 12 cm ikiye bölünür: |BH| = 6 cm, |HC| = 6 cm ve |DH| = 6 - 3 = 3 cm olur. ABH üçgeninde |AH| = √(10² - 6²) = 8 cm ve AHD üçgeninde |AD| = √(8² + 3²) = √73 cm bulunur.'),
  ('İkizkenar bir ABC üçgeninde |AB| = |AC| = 8 birimdir. [BC] kenarının C yönündeki uzantısı üzerinde |BD| = 11 birim ve |CD| = 5 birim olacak biçimde D noktası alındığına göre |AD| uzunluğu kaç birimdir?', '√119 birim', ['10 birim', '√109 birim', '11 birim'], '|BC| = 11 - 5 = 6 birim olup A\'dan [BC]\'ye inen dikme ayağı H için |BH| = |HC| = 3 birim ve |AH|² = 8² - 3² = 55 olur. |HD| = 3 + 5 = 8 birim olduğundan AHD dik üçgeninde |AD| = √(55 + 8²) = √119 birim bulunur.'),
  ('|KL| = |KM| olan ikizkenar KLM üçgeninde [LM] tabanının uzantısı üzerindeki bir P noktasından [KL] doğrusuna indirilen dikmenin uzunluğu 14 birim, [KM] kenarına indirilen dikmenin uzunluğu ise 5 birimdir. Eş kenarlardan birine ait yükseklik kaç birimdir?', '9 birim', ['9,5 birim', '11 birim', '19 birim'], 'İkizkenar üçgende tabanın uzantısı üzerindeki bir noktadan yan kenar doğrularına indirilen dikmelerin farkı, yan kenar yüksekliğini verir: 14 - 5 = 9 birim.'),
  ('|AB| = |AC| olan ikizkenar bir ABC üçgeninde [BC] tabanı üzerindeki K noktasından eş kenarlara paralel çizilen iki doğru parçası yan kenarlarla bir paralelkenar oluşturmaktadır. Bu paralelkenarın çevresi 26 cm olduğuna göre eş kenarlardan birinin uzunluğu kaç santimetredir?', '13 cm', ['6,5 cm', '12 cm', '26 cm'], 'Tabandaki noktadan eş kenarlara çizilen paralellerin uzunlukları toplamı bir eş kenar uzunluğuna (a) eşittir. Paralelkenarın karşılıklı kenarları eşit olduğundan çevresi 2a = 26 cm ve a = 13 cm olur.'),
  ('Eşkenar bir ABC üçgeninin iç bölgesinde seçilen P noktasından üç kenara indirilen dikmelerin uzunlukları 2√3 cm, 3√3 cm ve 5√3 cm olduğuna göre bu üçgenin bir kenar uzunluğu kaç santimetredir?', '20 cm', ['10√3 cm', '18 cm', '24 cm'], 'Viviani teoremine göre eşkenar üçgenin içindeki bir noktadan kenarlara indirilen dikmelerin toplamı üçgenin yüksekliğine eşittir: h = 2√3 + 3√3 + 5√3 = 10√3 cm. Buradan a√3 / 2 = 10√3 => a = 20 cm bulunur.'),
  ('Eşkenar bir KLM üçgeninin iç bölgesindeki T noktasından üç kenara ayrı ayrı paralel doğru parçaları çizilerek kenarlara kadar uzatılıyor. Bu üç paralel parçanın uzunlukları 4 birim, 6 birim ve 7 birim ise KLM üçgeninin çevresi kaç birimdir?', '51 birim', ['34 birim', '48 birim', '54 birim'], 'Eşkenar üçgenin iç bölgesindeki bir noktadan üç kenara çizilen paralellerin toplamı bir kenar uzunluğuna eşittir: a = 4 + 6 + 7 = 17 birim. Üçgenin çevresi 3 · 17 = 51 birim olur.'),
  ('ABC eşkenar üçgeninin [BC] tabanı üzerinde |BD| = 2 cm ve |DC| = 6 cm olacak biçimde bir D noktası işaretleniyor. Buna göre |AD| doğru parçasının uzunluğu kaç santimetredir?', '2√13 cm', ['6 cm', '4√3 cm', '2√15 cm'], 'Bir kenar |BC| = 8 cm olup A\'dan [BC]\'ye inen dikme ayağı H için |BH| = 4 cm, |DH| = 4 - 2 = 2 cm ve yükseklik |AH| = 4√3 cm olur. AHD dik üçgeninde |AD| = √((4√3)² + 2²) = √(48 + 4) = √52 = 2√13 cm bulunur.'),
  ('Dik kenarları 1 birim olan ikizkenar dik üçgenden başlayıp her adımda bir önceki hipotenüse dik 1 birimlik yeni dik kenar ekleyerek √2, √3, √4, √5... uzunluklarını üreten geometrik yapı literatürde hangi adla anılır?', 'Theodoros sarmalı', ['Arşimet spirali', 'Euler çemberi', 'Pappus zinciri'], 'Kireneli Theodoros\'un irrasyonel karekök uzunluklarını ardışık dik üçgenlerle inşa ettiği bu şekil Theodoros (veya karekök) sarmalı olarak bilinir.'),
  ('Theodoros sarmalında dik kenarları 1 birim ve 1 birim olan birinci dik üçgenden başlanarak her adımda hipotenüse 1 birimlik dik kenar eklendiğinde, sekizinci dik üçgenin hipotenüs uzunluğu kaç birim olur?', '3 birim', ['2√2 birim', '√10 birim', '4 birim'], 'Birinci üçgenin hipotenüsü √2, ikinci üçgenin √3, ..., n\'inci dik üçgenin hipotenüsü √(n + 1) olur; sekizinci üçgenin hipotenüsü √(8 + 1) = √9 = 3 birimdir.'),
  ('Bir dik üçgenin kenar uzunlukları ardışık çift tam sayılardan oluştuğuna göre bu üçgenin çevre uzunluğu kaç birimdir?', '24 birim', ['12 birim', '30 birim', '36 birim'], 'Kenarlar 2n - 2, 2n ve 2n + 2 yazılıp Pisagor bağıntısı uygulandığında (2n - 2)² + (2n)² = (2n + 2)² => 4n² = 16n => n = 4 bulunur; kenarlar 6, 8 ve 10 olup çevre 24 birimdir.'),
  ('Genişliği 80 cm olan bir kapı kasasının yüksekliği 150 cm\'dir. İnce bir kare kontrplak levhanın eğik tutularak bu kapıdan geçebilmesi için bir kenar uzunluğu teorik olarak en fazla kaç santimetreye kadar yaklaşabilir?', '170 cm', ['150 cm', '160 cm', '230 cm'], 'Levhanın kapıdan geçebileceği en geniş açıklık kapının köşegenidir; 8-15-17 üçgeninin 10 katından köşegen √(80² + 150²) = 170 cm olur.'),
  ('m(A) = 90° olan bir ABC dik üçgeninde [AH] ⊥ [BC] olup |AB| = 2√5 cm ve |HC| = 8 cm olarak veriliyor. Buna göre |BH| uzunluğu kaç santimetredir?', '2 cm', ['1 cm', '2,5 cm', '4 cm'], '|BH| = x denirse Öklid dik kenar bağıntısından |AB|² = |BH| · |BC| => (2√5)² = x · (x + 8) => x² + 8x - 20 = 0 => (x + 10)(x - 2) = 0 denkleminden x = 2 cm bulunur.'),
  ('m(A) = 90° olan bir ABC dik üçgeninde [AH] ⊥ [BC] çiziliyor. |AC| = 6 cm ve |BH| = 5 cm olduğuna göre |HC| uzunluğu kaç santimetredir?', '4 cm', ['3 cm', '4,5 cm', '5 cm'], '|HC| = k denirse Öklid bağıntısından |AC|² = k · (k + 5) => 36 = k² + 5k => (k + 9)(k - 4) = 0 denkleminden pozitif uzunluk k = 4 cm bulunur.'),
  ('Bir sarkaç tavandaki sabit noktasından aşağıya doğru 25 cm uzunluğundaki iple sarkmaktadır. Sarkaç topu denge konumundan yatayda 7 cm yana çekildiğinde düşeyde kaç santimetre yükselir?', '1 cm', ['1,5 cm', '2 cm', '3 cm'], 'İp uzunluğu 25 cm sabit kaldığından top 7 cm yana açıldığında tavana düşey uzaklığı √(25² - 7²) = 24 cm olur. Denge konumunda 25 cm aşağıda olduğundan yükselme miktarı 25 - 24 = 1 cm\'dir.'),
  ('m(ABC) = 90°, m(ACB) = 30° ve |AC| = 16 cm olan bir dik üçgende [BC] kenarının orta noktası D olarak işaretleniyor. Buna göre |AD| uzunluğu kaç santimetredir?', '4√7 cm', ['8√2 cm', '10 cm', '6√3 cm'], '30°-60°-90° üçgeninde 30° karşısı |AB| = 8 cm ve 60° karşısı |BC| = 8√3 cm olur. D orta nokta olduğundan |BD| = 4√3 cm\'dir; ABD dik üçgeninde |AD| = √(8² + (4√3)²) = √(64 + 48) = √112 = 4√7 cm bulunur.'),
  ('Eşkenar bir ABC üçgeninde [AB] kenarı üzerinde |AD| = 3 cm ve |DB| = 5 cm olacak şekilde D noktası alınıyor; D noktasından [BC] kenarına indirilen dikmenin ayağı E olduğuna göre |EC| kaç santimetredir?', '11/2 cm', ['5 cm', '9/2 cm', '6 cm'], 'Eşkenar üçgenin bir kenarı 3 + 5 = 8 cm ve m(B) = 60° olur. BDE (30°-60°-90°) dik üçgeninde hipotenüs |DB| = 5 cm olduğundan 30° karşısı |BE| = 5/2 cm ve |EC| = 8 - 5/2 = 11/2 cm bulunur.'),
  ('Tepe açısı 120° olan ikizkenar bir üçgenin taban uzunluğu 18 cm olduğuna göre bu üçgenin çevre uzunluğu kaç santimetredir?', '18 + 12√3 cm', ['18 + 9√3 cm', '18 + 18√3 cm', '36 cm'], '120° karşısı a√3 = 18 cm ise eş yan kenarlardan her biri a = 18 / √3 = 6√3 cm olur; çevre 18 + 6√3 + 6√3 = 18 + 12√3 cm elde edilir.'),
  ('m(BAC) = 45°, |AB| = 6√2 birim ve |AC| = 14 birim olan bir ABC üçgeninde |BC| kenarının uzunluğu kaç birimdir?', '10 birim', ['8√2 birim', '9 birim', '12 birim'], 'B köşesinden [AC] kenarına [BH] dikmesi indirildiğinde 45°-45°-90° üçgeninden |AH| = |BH| = 6 birim ve |HC| = 14 - 6 = 8 birim olur. BHC (6-8-10) dik üçgeninden |BC| = 10 birim elde edilir.'),
  ('Pisagor teoremini kanıtlamak için kenar uzunluğu (a + b) olan büyük bir karenin içine eş dört adet dik üçgen yerleştirildiğinde ortada kalan boş bölgenin geometrik şekli ve bir kenar uzunluğu nedir?', 'Kenarı hipotenüs c olan bir kare', ['Kenarları a ve b olan dikdörtgen', 'Çapı c olan bir daire dilimi', 'Tabanı a + b olan ikizkenar üçgen'], 'Eş dört dik üçgenin dar açıları tümler olduğundan ortadaki dörtgenin her iç açısı 180° - 90° = 90° ve her kenarı hipotenüs c uzunluğunda bir kare olur.'),
  ('Pozitif m > n tam sayıları için a = m² - n², b = 2mn ve c = m² + n² Öklid formülleri kullanılarak m = 4 ve n = 3 seçildiğinde elde edilen ilkel Pisagor üçlüsü aşağıdakilerden hangisidir?', '(7, 24, 25)', ['(8, 15, 17)', '(5, 12, 13)', '(9, 40, 41)'], 'm = 4 ve n = 3 değerleri yerine konulduğunda a = 16 - 9 = 7, b = 2·4·3 = 24 ve c = 16 + 9 = 25 olup (7, 24, 25) üçlüsü üretilir.'),
  ('m(BAC) = 90° ve [AH] ⊥ [BC] olan bir ABC dik üçgeninde |AB| = c, |AC| = b ve yükseklik |AH| = h sembolleriyle gösterildiğinde 1/b² + 1/c² toplamı aşağıdakilerden hangisine daima eşittir?', '1/h²', ['2/h²', '1/(b·c)', 'h²/(b²·c²)'], '1/b² + 1/c² = (b² + c²) / (b²·c²) = a² / (a·h)² = 1/h² ters kareler (ters Pisagor) özdeşliği her dik üçgende geçerlidir.'),
  ('Dik kenarları b ve c, hipotenüse ait yüksekliği h olan bir dik üçgende 1/b² + 1/c² = 1/16 bağıntısı veriliyor. Buna göre hipotenüse ait yükseklik h kaç birimdir?', '4 birim', ['2 birim', '8 birim', '16 birim'], 'Dik üçgende 1/h² = 1/b² + 1/c² bağıntısı uyarınca 1/h² = 1/16 eşitliğinden h² = 16 ve h = 4 birim bulunur.'),
  ('[BC] tabanının aynı tarafında çizilen ABC ve DBC dik üçgenlerinde m(BAC) = m(BDC) = 90° ve |BC| = 18 birimdir. [BC] kenarının orta noktası M olduğuna göre MAD üçgeninin ikizkenar veya eşkenarlığı için |MA| + |MD| toplamı kaç birimdir?', '18 birim', ['9 birim', '12√2 birim', '27 birim'], 'Her iki dik üçgende de M hipotenüsün orta noktası olduğundan muhteşem üçlü gereği |MA| = 18/2 = 9 birim ve |MD| = 18/2 = 9 birimdir; toplamları 9 + 9 = 18 birim olur.'),
  ('İkizkenar bir ABC üçgeninde |AB| = |AC|, m(BAC) = 30° ve B köşesinden [AC] yan kenarına indirilen dikmenin uzunluğu 6 cm ise bu üçgenin eş kenarlarından birinin uzunluğu kaç santimetredir?', '12 cm', ['6√3 cm', '8√3 cm', '12√3 cm'], 'B\'den [AC]\'ye indirilen dikme [BH] ile oluşan ABH dik üçgeninde m(A) = 30° ve 30° karşısı |BH| = 6 cm olduğundan hipotenüs olan eş kenar |AB| = 12 cm elde edilir.'),
  ('Merdiven basamaklarından oluşan dik kesitli bir yapıda her bir basamağın düşey rıht yüksekliği 15 cm, yatay basamak genişliği ise 20 cm\'dir. En alt basamağın ön ucundan 8. basamağın üst arka köşesine gerilen doğrusal şeridin uzunluğu kaç metredir?', '2 metre', ['1,6 metre', '2,4 metre', '2,8 metre'], '8 basamak boyunca toplam düşey yükseklik 8 · 15 = 120 cm, toplam yatay genişlik 8 · 20 = 160 cm olur. Doğrusal uzaklık √(120² + 160²) = 200 cm = 2 metredir.'),
  ('Çevresi 36 cm olan eşkenar üçgen biçimindeki bir kartonun her köşesinden kenarı 2 cm olan küçük birer eşkenar üçgen kesilip atılıyor. Kalan altıgenin çevresi kaç santimetredir?', '30 cm', ['24 cm', '28 cm', '32 cm'], 'İlk eşkenar üçgenin bir kenarı 12 cm\'dir. Her köşeden kenarı 2 cm olan eşkenar üçgen kesildiğinde giden 2 + 2 = 4 cm yerine 2 cm\'lik yeni kenar gelir; her köşede çevre 2 cm azaldığından 36 - 3·2 = 30 cm kalır.'),
  ('Bir ABC üçgeninde [AB] ⊥ [AC] ve [AD] ⊥ [BC] olup |BD| = x + 1, |DC| = x + 6 ve |AD| = 6 birim olduğuna göre |BC| hipotenüsünün uzunluğu kaç birimdir?', '13 birim', ['12 birim', '14 birim', '15 birim'], 'Öklid yükseklik bağıntısından 6² = (x + 1)(x + 6) => x² + 7x - 30 = 0 => (x + 10)(x - 3) = 0 denkleminden x = 3 bulunur. Hipotenüs parçaları 4 ve 9 birim olduğundan |BC| = 4 + 9 = 13 birimdir.'),
  ('Bir dik üçgenin hipotenüs uzunluğu 25 cm, dik kenarlarının uzunlukları toplamı ise 31 cm olduğuna göre bu üçgenin dik kenarlarının uzunlukları çarpımı kaç santimetrekaredir?', '168 cm²', ['144 cm²', '156 cm²', '180 cm²'], 'Dik kenarlar b ve c için b + c = 31 ve Pisagor\'dan b² + c² = 25² = 625 olur. (b + c)² = b² + c² + 2bc => 961 = 625 + 2bc => 2bc = 336 => bc = 168 cm² bulunur.'),
  ('Yatay düzlem üzerindeki bir dron önce yerden dikey olarak 20 metre yükseliyor, sonra irtifasını değiştirmeden kuzeye 15 metre, ardından yine irtifasını değiştirmeden doğuya 36 metre uçuyor. Dronun son konumu ile kalkış noktası arasındaki doğrusal uzaklık kaç metredir?', '√1921 metre', ['39 metre', '41 metre', '√1841 metre'], 'Yatay düzlemdeki kuzey ve doğu yer değiştirmelerinin bileşkesi 15-36-39 dik üçgeninden 39 metredir. Düşey yükseklik 20 metre olduğundan kalkış noktasına uzaklık √(39² + 20²) = √(1521 + 400) = √1921 metredir.'),
  ('Uzunluğu 18 birim olan doğrusal bir çubuk, bir ucundan 6 birim içerideki noktadan 120 derecelik iç açı oluşturacak şekilde bükülüyor. Çubuğun iki ucu arasındaki doğrusal uzaklık kaç birimdir?', '6√7 birim', ['12√2 birim', '6√5 birim', '15 birim'], 'Kenarları 6 birim ve 12 birim, aradaki açısı 120° olan üçgende 6 birimlik kol uzatılıp 12\'lik uçtan dikme inerse 30°-60°-90° üçgeninden dik kenarlar 6√3 ve 6 + 6 = 12 olur; hipotenüs √((6√3)² + 12²) = √(108 + 144) = √252 = 6√7 birimdir.'),
  ('Aşağıdaki veri gruplarından hangisinin iki üçgen arasında karşılıklı eşit olması, üçgenlerin kesinlikle eş olmasını sağlamaz?', 'İki kenar ve bunlara komşu olmayan bir açı', ['Üç kenar uzunluğunun tamamı', 'İki kenar ve aralarındaki açı', 'Bir kenar ve uçlarındaki iki dar açı'], 'Kenar-Kenar-Açı (KKA) durumunda dar açılı ve geniş açılı iki farklı üçgen oluşabileceğinden bu koşul genel olarak eşlik teoremi değildir.'),
  ('ABCD karesinin dış bölgesinden geçen bir d doğrusu yalnızca B köşesine değmektedir. A ve C köşelerinden d doğrusuna indirilen dikme ayakları K ve L olup |AK| = 5 birim ve |CL| = 12 birim olduğuna göre |KL| uzunluğu kaç birimdir?', '17 birim', ['7 birim', '13 birim', '15 birim'], 'm(KBA) + m(LBC) = 90° ve |AB| = |BC| olduğundan AKB ≅ BLC dik üçgen eşliği oluşur. Buradan |BL| = |AK| = 5 birim ve |KB| = |CL| = 12 birim olup |KL| = 12 + 5 = 17 birimdir.'),
  ('Ortak A köşesine sahip eşkenar ABC ve eşkenar ADE üçgenleri düzlemde D noktası üçgenin dışında kalacak biçimde çiziliyor (B, A, D doğrusal değil). |BD| = 14 mm olduğuna göre |CE| doğru parçasının uzunluğu kaç milimetredir?', '14 mm', ['7 mm', '7√3 mm', '28 mm'], '|AB| = |AC|, |AD| = |AE| ve m(BAD) = 60° + m(CAD) = m(CAE) olduğundan KAK eşlik teoremiyle ABD ≅ ACE olur; karşılıklı kenarlardan |CE| = |BD| = 14 mm bulunur.'),
  ('İkizkenar bir üçgende eş olan yan kenarlara ait yüksekliklerin uzunluklarının birbirine eşit olması, aşağıdaki eşlik kurallarından hangisiyle kanıtlanır?', 'Açı-Açı-Kenar dik üçgen eşliği', ['Kenar-Kenar-Kenar eşlik kuralı', 'Yalnızca Tales paralel orantısı', 'Muhteşem üçlü kenarortay kuralı'], 'Taban üzerinde oluşan iki dik üçgende taban hipotenüsü ortaktır, taban açıları eşittir ve birer açı 90° olduğundan Açı-Açı-Kenar eşliğiyle yükseklikler eşit çıkar.'),
  ('ABCD yamuğunda [AB] // [EF] // [DC] olacak şekilde yan kenarlar üzerinde E ∈ [AD] ve F ∈ [BC] noktaları alınıyor. |AB| = 7 birim, |DC| = 19 birim ve 2|AE| = |ED| olduğuna göre |EF| doğru parçasının uzunluğu kaç birimdir?', '11 birim', ['10 birim', '13 birim', '15 birim'], '|AE| = k ve |ED| = 2k alınırsa 3k ilerlemede paralel uzunluk 19 - 7 = 12 birim arttığından k ilerlemede 4 birim artar; |EF| = 7 + 4 = 11 birim bulunur.'),
  ('Köşegen uzunlukları |AC| = 16 cm ve |BD| = 22 cm olan dışbükey bir ABCD dörtgeninin dört kenarının orta noktaları ardışık birleştirilerek KLMN dörtgeni oluşturuluyor. KLMN dörtgeninin çevresi kaç santimetredir?', '38 cm', ['19 cm', '32 cm', '44 cm'], 'Orta taban teoremine göre karşılıklı iki kenar |AC|/2 = 8 cm, diğer iki kenar |BD|/2 = 11 cm uzunluğundadır; çevre 8 + 8 + 11 + 11 = 38 cm olur.'),
  ('Yatay düzleme dik duran 6 metre ve 12 metre boyundaki iki direğin her birinin tepesinden diğerinin dip noktasına gergin birer çelik halat çekiliyor. İki halatın kesiştiği noktanın yerden yüksekliği kaç metredir?', '4 metre', ['3 metre', '4,5 metre', '5 metre'], 'Aynı düzleme dik iki paralel doğru arasındaki çapraz kesenlerin kesişim yüksekliği h için 1/h = 1/a + 1/b bağıntısı geçerlidir: 1/h = 1/6 + 1/12 = 1/4 => h = 4 metre bulunur.'),
  ('Paralelkenar biçimindeki ABCD bahçesinde E noktası [DC] kenarının orta noktasıdır. [AE] doğru parçası ile [BD] köşegeni K noktasında kesiştiğine ve |BD| = 27 metre olduğuna göre |KD| uzunluğu kaç metredir?', '9 metre', ['6,75 metre', '13,5 metre', '18 metre'], '|DE| = |DC|/2 = |AB|/2 olduğundan EKD ile AKB üçgenleri arasındaki kelebek benzerlik oranı 1/2 olur. |KD| / |KB| = 1 / 2 olduğundan 3|KD| = 27 ve |KD| = 9 metre bulunur.'),
  ('Çeşitkenar bir ABC üçgeninde D ∈ [AB] ve E ∈ [AC] noktaları için m(ADE) = m(ACB) eşitliği veriliyor. |AD| = 4 cm, |DB| = 8 cm ve |AE| = 6 cm olduğuna göre |EC| uzunluğu kaç santimetredir?', '2 cm', ['3 cm', '6 cm', '12 cm'], 'A açısı ortak ve m(ADE) = m(ACB) olduğundan ADE ~ ACB ters-benzerliği yazılır: |AD| / |AC| = |AE| / |AB| => 4 / (6 + |EC|) = 6 / 12 => 6 + |EC| = 8 => |EC| = 2 cm bulunur.'),
  ('P köşesi ortak olan PRS ve PKL üçgenlerinde K ∈ [PR], L ∈ [PS] olup |PK| = 3 birim, |KR| = 7 birim, |PL| = 5 birim ve |LS| = 1 birimdir. |KL| = 4 birim olduğuna göre |RS| kenarının uzunluğu kaç birimdir?', '8 birim', ['6 birim', '9 birim', '10 birim'], 'PKL üçgeninde P açısını oluşturan kenarlar 3 ve 5 birim; PRS üçgeninde |PS| = 6 ve |PR| = 10 birimdir. 3/6 = 5/10 = 1/2 ve m(P) ortak olduğundan KAK benzerliğinden PKL ~ PSR olup |KL| / |RS| = 1 / 2 => |RS| = 8 birim olur.'),
  ('D noktası [BC] kenarı üzerinde bulunan bir ABC üçgeninde m(BAD) = m(ACB) eşitliği sağlanmaktadır. |BD| = 5 cm ve |DC| = 15 cm olduğuna göre |AB| kenarının uzunluğu kaç santimetredir?', '10 cm', ['8 cm', '5√3 cm', '12 cm'], 'm(B) ortak ve m(BAD) = m(ACB) olduğundan ABD ~ CBA benzerliği kurulur: |AB| / |BC| = |BD| / |AB| => |AB|² = |BD| · |BC| = 5 · 20 = 100 => |AB| = 10 cm bulunur.'),
  ('Yatay zemine bırakılan küçük bir düzlem aynaya 3 metre uzaklıkta duran ve göz yüksekliği yerden 1,6 metre olan bir gözlemci, aynada karşıdaki dik binanın tam tepe noktasını görüyor. Ayna ile bina tabanı arasındaki uzaklık 24 metre olduğuna göre binanın yüksekliği kaç metredir?', '12,8 metre', ['11,2 metre', '12,4 metre', '14,4 metre'], 'Düzlem aynada gelme ve yansıma açıları eşit olduğundan AA benzerliği oluşur: h / 24 = 1,6 / 3 => h = 8 · 1,6 = 12,8 metre elde edilir.'),
  ('Karşı kıyıya geçmeden nehir genişliğini ölçmek isteyen topoğraf, karşı kıyıdaki A ağacının tam karşısına B kazığını, kıyı boyunca [AB]\'ye dik 30 metre yürüyüp C kazığını, aynı doğrultuda 10 metre daha yürüyüp D kazığını çakıyor. D\'den kıyıya dik iç tarafa doğru 18 metre gittiğinde E noktasından C ve A\'yı doğrusal gördüğüne göre nehir genişliği |AB| kaç metredir?', '54 metre', ['45 metre', '48 metre', '60 metre'], 'ABC ve EDC dik üçgenleri ters açılar ve dik açılardan dolayı benzerdir: |AB| / |DE| = |BC| / |CD| => |AB| / 18 = 30 / 10 = 3 => |AB| = 54 metre bulunur.'),
  ('Dik kenarları |AB| = 12 cm ve |BC| = 18 cm olan ABC dik üçgeninin (m(B) = 90°) içine, bir köşesi B ve karşı köşesi E ∈ [AC] hipotenüsü üzerinde olacak biçimde BDEF karesi yerleştiriliyor. Karenin bir kenar uzunluğu kaç santimetredir?', '36/5 cm', ['6 cm', '7 cm', '15/2 cm'], 'Karenin kenarı x denirse [FE] // [BC] olduğundan AFE ~ ABC benzerliği oluşur: (12 - x) / 12 = x / 18 => 3(12 - x) = 2x => x = 36/5 cm bulunur.'),
  ('Taban uzunluğu |BC| = 20 cm ve bu tabana ait yüksekliği h = 15 cm olan dar açılı bir üçgenin içine, iki köşesi [BC] üzerinde ve üstteki iki köşesi yan kenarlar üzerinde olan bir kare çiziliyor. Karenin bir kenarı kaç santimetredir?', '60/7 cm', ['8 cm', '9 cm', '75/8 cm'], 'Karenin kenarı x ise üstte kalan küçük üçgenin yüksekliği 15 - x ve tabanı x olur. Temel benzerlikten x / 20 = (15 - x) / 15 => 3x = 4(15 - x) => x = 60/7 cm elde edilir.'),
  ('Alanları oranı 16/81 olan benzer iki üçgenden büyüğünün çevresi 63 birim olduğuna göre küçüğünün çevresi kaç birimdir?', '28 birim', ['14 birim', '21 birim', '36 birim'], 'Alanlar oranı benzerlik oranının karesine eşittir: k² = 16/81 => k = 4/9. Çevreler oranı da 4/9 olduğundan Çevre / 63 = 4 / 9 => Çevre = 28 birim olur.'),
  ('Ölçeği 1/50.000 olan topografik bir haritada kenar uzunlukları 6 cm, 8 cm ve 10 cm olan dik üçgen biçimindeki bir koruluk gerçekte kaç kilometrekare alan kaplar?', '6 km²', ['1,2 km²', '3 km²', '12 km²'], '1 cm haritada 50.000 cm = 0,5 km gerçek uzunluğu gösterir. Gerçek dik kenarlar 6 · 0,5 = 3 km ve 8 · 0,5 = 4 km olduğundan gerçek alan (3 · 4) / 2 = 6 km² bulunur.'),
  ('İki benzer üçgenin iç teğet çemberlerinin yarıçapları oranı 5/8 olduğuna göre büyük üçgenin çevrel çember yarıçapının küçük üçgenin çevrel çember yarıçapına oranı kaçtır?', '8/5', ['5/8', '25/64', '64/25'], 'Küçük üçgenin büyüğe benzerlik oranı iç teğet yarıçapları oranından 5/8\'dir. Tüm doğrusal yarıçaplar aynı benzerlik oranına uyduğundan büyüğün çevrel yarıçapının küçüğünkine oranı 8/5 olur.'),
  ('Doğrusal [BD] zemini üzerindeki E noktasında m(AEC) = 90° olup [AB] ⊥ [BD] ve [CD] ⊥ [BD] diklikleri veriliyor. |AB| = 6 cm, |BE| = 8 cm ve |CD| = 12 cm olduğuna göre |ED| uzunluğu kaç santimetredir?', '9 cm', ['6 cm', '8 cm', '10 cm'], 'm(AEB) + m(CED) = 90° olduğundan tümler açılar gereği ABE ~ ECD dik üçgen benzerliği oluşur: |AB| / |ED| = |BE| / |CD| => 6 / |ED| = 8 / 12 => |ED| = 9 cm bulunur.'),
  ('Yatay zemin ile düşey duvarın birleştiği köşeye bir ayrıtı 6 dm olan küp biçiminde bir sandık tam yaslanıyor. Sandığın üst ayrıtına teğet geçen doğrusal kalasın alt ucu sandıktan 8 dm uzakta zemine değdiğine göre üst ucu sandığın üst yüzeyinden kaç desimetre yukarıda duvara değer?', '4,5 dm', ['4 dm', '5 dm', '6 dm'], 'Sandığın sağında ve üstünde oluşan iki dik üçgen yöndeş açılardan dolayı benzerdir: h / 6 = 6 / 8 => h = 36 / 8 = 4,5 dm bulunur.'),
  ('ABC üçgeninde B ve C köşelerine ait iç açıortayların kesim noktası olan I\'dan [BC] tabanına paralel çizilen doğru [AB] kenarını D, [AC] kenarını E noktasında kesiyor. |AB| = 13 cm ve |AC| = 17 cm olduğuna göre ADE üçgeninin çevresi kaç santimetredir?', '30 cm', ['26 cm', '34 cm', '15 cm'], 'İç ters açılar ve açıortaylardan |DI| = |DB| ve |EI| = |EC| ikizkenarlıkları oluşur. Çevre(ADE) = |AD| + |DI| + |IE| + |AE| = (|AD| + |DB|) + (|AE| + |EC|) = |AB| + |AC| = 13 + 17 = 30 cm olur.'),
  ('Alt tabanı |AB| = 15 birim ve üst tabanı |DC| = 10 birim olan bir ABCD yamuğunda ([AB] // [DC]), köşegenlerin kesim noktası olan O\'dan tabanlara paralel çizilen ve yan kenarları E ile F\'de kesen [EF] doğru parçasının uzunluğu kaç birimdir?', '12 birim', ['11 birim', '12,5 birim', '13 birim'], 'Kelebek ve temel benzerlik birleştirildiğinde köşegen kesim noktasından geçen paralel parça tabanların harmonik ortalamasıdır: |EF| = 2·a·c / (a + c) = (2 · 15 · 10) / (15 + 10) = 300 / 25 = 12 birim.'),
  ('[AB] kenarı üzerinde D ve E noktaları (A-D-E-B sırasıyla), [AC] kenarı üzerinde F ve K noktaları (A-F-K-C sırasıyla) alınarak [DF] // [EK] // [BC] paralellikleri oluşturuluyor. |AD| = |DE| = |EB| ve |DF| + |EK| = 18 cm olduğuna göre |BC| tabanı kaç santimetredir?', '18 cm', ['15 cm', '24 cm', '27 cm'], 'Eşit aralıklı paralellerde |DF| = k, |EK| = 2k ve |BC| = 3k olur. k + 2k = 18 => 3k = 18 cm olduğundan |BC| = 3k = 18 cm elde edilir.'),
  ('Bir kenar uzunluğu 12 cm olan eşkenar ABC üçgeninde [BC] tabanına paralel çizilen [DE] doğru parçası (D ∈ [AB], E ∈ [AC]) üçgeni üstte küçük bir üçgene ve altta DBCE ikizkenar yamuğuna ayırıyor. DBCE yamuğunun çevresi 31 cm olduğuna göre |DE| kaç santimetredir?', '5 cm', ['4 cm', '6 cm', '7 cm'], '[DE] // [BC] olduğundan ADE de eşkenar üçgendir ve |AD| = |AE| = |DE| = x olur. Yan kenarlar |DB| = |EC| = 12 - x olduğundan yamuğun çevresi (12 - x) + 12 + (12 - x) + x = 36 - x = 31 => x = 5 cm bulunur.'),
  ('Fotoğrafçılıkta 50 mm odak uzaklığına sahip bir merceğin optik merkezinden 2,5 metre uzağa yerleştirilen üçgen bir flamanın sensör üzerinde oluşan benzer görüntüsü gerçek boyutunun kaçta kaçıdır?', '1/50', ['1/25', '1/40', '1/100'], '2,5 metre = 2500 mm olduğundan optik merkezdeki kelebek benzerliği uyarınca görüntü boyunun cisim boyuna oranı 50 / 2500 = 1/50 olur.'),
  ('Yerden yüksekliği 3,2 metre olan bir projektör, kendisinden 6 metre ileride yere dik duran 1,2 metre yüksekliğindeki bahçe duvarının üzerinden aşarak duvarın arkasındaki düz zemini aydınlatıyor. Duvarın arkasında kalan karanlık gölge şeridinin genişliği kaç metredir?', '3,6 metre', ['3 metre', '3,2 metre', '4 metre'], 'Gölge genişliğine x metre denirse temel benzerlikten x / (x + 6) = 1,2 / 3,2 = 3 / 8 => 8x = 3x + 18 => 5x = 18 => x = 3,6 metre bulunur.'),
  ('Ütü masasının eşit uzunlukta olmayan çapraz iki ayağı K noktasında pimle birbirine bağlanmıştır; üst tabla ile yatay zemin birbirine paraleldir. Ayakların üst uçları arasındaki açıklık 36 cm, alt uçları arasındaki açıklık 54 cm ve K piminin zemine dik uzaklığı 48 cm ise ütü masasının yerden toplam yüksekliği kaç santimetredir?', '80 cm', ['72 cm', '76 cm', '84 cm'], 'Kelebek benzerliğinde üst üçgen ile alt üçgenin yükseklikleri oranı tabanları oranına eşittir: h_üst / 48 = 36 / 54 = 2 / 3 => h_üst = 32 cm olur. Toplam yükseklik 48 + 32 = 80 cm bulunur.'),
  ('Tahterevallinin tam ortasında olmayan destek noktası, sol uca 1,2 metre, sağ uca ise 1,8 metre uzaklıktadır. Sol uç düz zemine değdiği anda sağ uç yerden 1,5 metre yüksekte bulunduğuna göre destek noktasının yerden yüksekliği kaç santimetredir?', '60 cm', ['50 cm', '75 cm', '90 cm'], 'Sol uçtan itibaren oluşan benzer dik üçgenlerde destek uzaklığının toplam boya oranı 1,2 / (1,2 + 1,8) = 1,2 / 3 = 2 / 5 olur. Destek yüksekliği h / 150 cm = 2 / 5 => h = 60 cm bulunur.'),
  ('m(B) = 90° olan ABC dik üçgeninde |AB| = 8 cm ve |BC| = 15 cm\'dir. Hipotenüs üzerindeki bir K noktasının [BC] kenarına olan dik uzaklığı 4 cm olduğuna göre aynı K noktasının [AB] kenarına olan dik uzaklığı kaç santimetredir?', '7,5 cm', ['6 cm', '7 cm', '8,5 cm'], 'K\'dan [BC]\'ye indirilen 4 cm\'lik dikme [AB]\'ye paraleldir ve 4 / 8 = 1 / 2 oranından K hipotenüsün orta noktasıdır. Dolayısıyla K\'dan [AB]\'ye indirilen dikme [BC]\'nin orta tabanı olur ve 15 / 2 = 7,5 cm bulunur.'),
  ('Kenar uzunlukları |AB| = 9 cm, |BC| = 12 cm ve |AC| = 15 cm olan bir üçgende [AB] kenarı üzerinde |AD| = 3 cm olacak şekilde D noktası, [AC] kenarı üzerinde |AE| = 5 cm olacak şekilde E noktası işaretleniyor. Buna göre |DE| doğru parçasının uzunluğu kaç santimetredir?', '4 cm', ['3,5 cm', '4,5 cm', '5 cm'], '|AD| / |AB| = 3 / 9 = 1 / 3 ve |AE| / |AC| = 5 / 15 = 1 / 3 oranları eşit ve A açısı ortak olduğundan KAK benzerliğiyle ADE ~ ABC olur; |DE| = |BC| / 3 = 12 / 3 = 4 cm bulunur.'),
  ('Bilardo masasında uzun bant üzerindeki K noktasından kısa banda 50 cm uzaklıktaki A topuna vurulduğunda top, uzun bandın K noktasına çarpıp yansıyarak K\'dan 120 cm ileride ve uzun banda 75 cm dik uzaklıktaki B deliğine giriyor. A topunun uzun banda dik uzaklığı 50 cm olduğuna göre K yansıma noktasının A topunun uzun banttaki dik iz düşümüne yatay uzaklığı kaç santimetredir?', '80 cm', ['60 cm', '75 cm', '90 cm'], 'Esnek çarpışmada geliş ve yansıma açıları bantla eşit dar açı oluşturduğundan iki dik üçgen benzerdir: x / 120 = 50 / 75 = 2 / 3 => x = 80 cm elde edilir.'),
  ('ABCD paralelkenarında F noktası [BC] kenarı üzerinde |BF| = 2|FC| olacak biçimde seçiliyor. [AF] ışını ile [DC] ışını uzatılarak E noktasında kesiştiriliyor. |AB| = 14 cm olduğuna göre |CE| uzunluğu kaç santimetredir?', '7 cm', ['6 cm', '8 cm', '10,5 cm'], '[AB] // [DE] olduğundan ABF ile ECF arasında kelebek benzerliği oluşur: |BF| / |FC| = |AB| / |CE| => 2 / 1 = 14 / |CE| => |CE| = 7 cm bulunur.'),
  ('Dar açılı bir ABC üçgeninde B köşesinden [AC]\'ye indirilen [BE] yüksekliği ile C köşesinden [AB]\'ye indirilen [CF] yüksekliği H noktasında kesişmektedir. |AF| = 5 birim, |FB| = 7 birim ve |AE| = 6 birim olduğuna göre |EC| uzunluğu kaç birimdir?', '4 birim', ['5 birim', '6 birim', '8 birim'], 'AEB ve AFC dik üçgenlerinde A açısı ortak olduğundan AEB ~ AFC benzerliği geçerlidir: |AE| / |AF| = |AB| / |AC| => 6 / 5 = (5 + 7) / (6 + |EC|) => 6 / 5 = 12 / (6 + |EC|) => 6 + |EC| = 10 => |EC| = 4 birim bulunur.'),
  ('İkizkenar bir ABC üçgeninde |AB| = |AC| = 15 cm ve |BC| = 18 cm\'dir. [AB] kenarının orta noktası D\'den [BC] tabanına indirilen dikmenin ayağı H olduğuna göre |BH| uzunluğu kaç santimetredir?', '4,5 cm', ['3 cm', '4 cm', '6 cm'], 'A tepe noktasından [BC]\'ye indirilen dikme ayağı K ise |BK| = 18 / 2 = 9 cm olur. [DH] // [AK] ve D orta nokta olduğundan [DH] ABK dik üçgeninin orta tabanıdır; |BH| = |BK| / 2 = 9 / 2 = 4,5 cm bulunur.'),
  ('KLM üçgeninde [KL] üzerinde A, [KM] üzerinde B noktası alınarak çizilen [AB] doğru parçası için |KA| = 6 cm, |AL| = 4 cm, |KB| = 5 cm ve |BM| = 7 cm ölçülüyor. |AB| = 7 cm olduğuna göre |LM| kenarının uzunluğu kaç santimetredir?', '14 cm', ['12 cm', '15 cm', '16 cm'], 'KAB üçgeninde K açısının kolları 5 ve 6 cm; KLM üçgeninde K açısının kolları |KL| = 10 cm ve |KM| = 12 cm\'dir. 5/10 = 6/12 = 1/2 ve K açısı ortak olduğundan KAK benzerliğinden KAB ~ KML olur; |LM| = 2 · |AB| = 14 cm elde edilir.'),
  ('Düzlemde verilen ABC ve KLM üçgenlerinde |AB| = 8 cm, |BC| = 12 cm, |AC| = 16 cm ve |KL| = 6 cm, |LM| = 9 cm, |KM| = 12 cm olarak ölçülüyor. Buna göre aşağıdaki açı eşitliklerinden hangisi kesinlikle doğrudur?', 'm(BAC) = m(LKM)', ['m(BAC) = m(KLM)', 'm(ABC) = m(KML)', 'm(ACB) = m(LKM)'], '8/6 = 12/9 = 16/12 = 4/3 olduğundan KKK benzerlik teoremiyle ABC ~ KLM benzerliği sağlanır; 12 cm\'lik [BC] kenarını gören m(BAC) açısı ile 9 cm\'lik [LM] kenarını gören m(LKM) açısı eşittir.'),
  ('Dik kenarları |AB| = 6 cm ve |AC| = 8 cm olan ABC dik üçgeninde (m(A) = 90°), A köşesinden hipotenüse [AH] yüksekliği indiriliyor. ABH üçgeninin çevresinin AHC üçgeninin çevresine oranı kaçtır?', '3/4', ['9/16', '2/3', '4/5'], 'Dik üçgende hipotenüse indirilen yükseklik, birbirine benzer iki dik üçgen oluşturur (ABH ~ CAH). Hipotenüsleri |AB| = 6 cm ve |AC| = 8 cm olduğundan çevreler oranı benzerlik oranı olan 6 / 8 = 3 / 4\'e eşittir.'),
  ('Antik Çağ\'da kıyıdaki yüksek bir kulenin tepesinde duran gözlemcinin, denizdeki gemiye bakış açısını bozmadan kuleyi karaya doğru döndürüp aynı bakış açısının karada düştüğü noktayla kule dibi arasındaki mesafeyi ölçerek gemi uzaklığını bulması hangi eşlik ilkesine dayanır?', 'Açı-Kenar-Açı (AKA) eşliği', ['Kenar-Kenar-Kenar (KKK) eşliği', 'Kenar-Açı-Açı benzerlik oranı', 'Öklid dik kenar iz düşümü'], 'Kule yüksekliği ortak kenar, kulenin zeminle/denizle yaptığı 90° ortak açı ve tepeden bakış açısı eşit tutulduğundan denizdeki ve karadaki dik üçgenler AKA kuralına göre eştir.'),
  ('Üç paralel doğru olan d1 // d2 // d3 sisteminde d2 doğrusu d1 ile d3 arasında yer almaktadır. Birinci kesen üzerinde d1-d2 arası 8 birim, d2-d3 arası 12 birimdir. İkinci kesen üzerinde d2-d3 arası, d1-d2 arasından 5 birim fazla olduğuna göre ikinci kesenin d1 ile d3 arasındaki toplam uzunluğu kaç birimdir?', '25 birim', ['20 birim', '24 birim', '30 birim'], 'Tales teoreminden parçalar oranı 8 / 12 = 2 / 3 olduğundan ikinci kesendeki parçalar 2k ve 3k olur. Farkları 3k - 2k = k = 5 birim olduğundan toplam uzunluk 5k = 25 birimdir.'),
  ('Kenar uzunlukları |AB| = 14 cm, |BC| = 16 cm ve |AC| = 20 cm olan ABC üçgeninde D, E ve F sırasıyla [AB], [BC] ve [AC] kenarlarının orta noktalarıdır. BDEF paralelkenarının çevresi, DEF üçgeninin çevresinden kaç santimetre fazladır?', '9 cm', ['7 cm', '8 cm', '10 cm'], 'Orta tabanlardan Çevre(BDEF) = 2(7 + 10) = 34 cm, Çevre(DEF) = (14 + 16 + 20) / 2 = 25 cm olur; aralarındaki fark 34 - 25 = 9 cm bulunur.'),
  ('Yüksekliği 2,1 metre olan bir kapı boşluğunun tam arkasında tavana asılı noktasal bir lamba yerden 2,8 metre yüksektedir ve kapı düzleminden yatayda 1,5 metre içeridedir. Kapı tamamen açıldığında ışık hüzmesinin kapının dışındaki koridor zemininde aydınlattığı bölgenin kapı eşiğinden itibaren uzunluğu kaç metredir?', '4,5 metre', ['3,5 metre', '4 metre', '6 metre'], 'Koridordaki aydınlık şerit uzunluğuna x metre denirse kapı üst kirişiyle oluşan benzer dik üçgenlerde x / (x + 1,5) = 2,1 / 2,8 = 3 / 4 => 4x = 3x + 4,5 => x = 4,5 metre bulunur.'),
  ('m(B) = 90° olan ABC dik üçgeninde [AC] hipotenüsü üzerindeki D noktasından [AB] kenarına [DE] dikmesi, [BC] kenarına [DF] dikmesi indiriliyor. |AE| = 4 cm ve |FC| = 9 cm olup BEDF şekli bir kare olduğuna göre bu karenin çevresi kaç santimetredir?', '24 cm', ['20 cm', '22 cm', '28 cm'], 'Karenin bir kenarı x ise yöndeş açılardan ADE ~ DFC dik üçgen benzerliği oluşur: |AE| / |DF| = |DE| / |FC| => 4 / x = x / 9 => x² = 36 => x = 6 cm ve karenin çevresi 4 · 6 = 24 cm elde edilir.'),
  ('Köşeleri P, R ve S olan bir üçgende [PR] kenarı üzerindeki K ve [PS] kenarı üzerindeki L noktaları için |PK| = 4 cm, |KR| = 8 cm, |PL| = 6 cm ve |LS| = 2 cm veriliyor. m(PKL) = 70° olduğuna göre m(PSR) açısı kaç derecedir?', '70°', ['35°', '55°', '110°'], '|PK| / |PS| = 4 / 8 = 1 / 2 ve |PL| / |PR| = 6 / 12 = 1 / 2 oranları eşit ve P açısı ortak olduğundan KAK benzerliğinden PKL ~ PSR elde edilir; dolayısıyla m(PSR) = m(PKL) = 70° olur.'),
  ('Düz bir arazide 2 metre yüksekliğindeki dikey bir çitin 3 metre gerisine dikilen 3,5 metre yüksekliğindeki direğin tepesindeki güvenlik kamerası, çitin üstünden aşarak çitin ön tarafındaki zemini en yakın kaç metre mesafeden itibaren görebilir?', '4 metre', ['3 metre', '4,5 metre', '5 metre'], 'Çitin önündeki ölü bölge uzunluğuna x metre denirse benzer dik üçgenlerden x / (x + 3) = 2 / 3,5 = 4 / 7 => 7x = 4x + 12 => 3x = 12 => x = 4 metre bulunur.'),
  ('ABC dik üçgeninde m(B) = 90°, |AB| = 6 birim ve |BC| = 8 birimdir. C köşesinden [AC]\'ye dik çizilen doğru [AB] ışınını D noktasında kestiğine göre |BD| uzunluğu kaç birimdir?', '32/3 birim', ['9 birim', '10 birim', '50/3 birim'], 'm(ACD) = 90° ve [BC] ⊥ [AD] olduğundan ADC büyük dik üçgeninde Öklid (veya ABC ~ CBD benzerliği) uygulanır: |BC|² = |AB| · |BD| => 8² = 6 · |BD| => |BD| = 64 / 6 = 32/3 birim bulunur.'),
  ('Dar açılı çeşitkenar bir üçgenin her köşesinden karşı kenara paralel birer doğru çizilerek dıştaki büyük KLM üçgeni oluşturuluyor. Başlangıçtaki üçgenin çevresi 29 cm olduğuna göre KLM üçgeninin çevresi kaç santimetredir?', '58 cm', ['43,5 cm', '87 cm', '116 cm'], 'Köşelerden karşı kenarlara çizilen paraleller üç adet paralelkenar oluşturur ve başlangıç üçgeni KLM üçgeninin orta taban (medial) üçgeni olur; benzerlik oranı 1/2 olduğundan KLM\'nin çevresi 2 · 29 = 58 cm\'dir.'),
  ('Ölçeği 1:200 olan mimari bir makette çatının ikizkenar üçgen biçimindeki alınlığının taban kenarı 16 cm ve yüksekliği 6 cm olarak tasarlanmıştır. Gerçek binadaki üçgen alınlığın eş olan yan kenarlarından birinin uzunluğu kaç metredir?', '20 metre', ['12 metre', '16 metre', '24 metre'], 'Makette taban 8 cm - 8 cm bölündüğünden yan kenar √(8² + 6²) = 10 cm olur. 1:200 ölçekle gerçek uzunluk 10 · 200 = 2000 cm = 20 metredir.'),
  ('Ortak [AC] kenarına sahip ABC ve ADC üçgenlerinde m(BAC) = m(DCA) ve m(BCA) = m(DAC) eşitlikleri veriliyor. Bu iki üçgen için aşağıdakilerden hangisi kesinlikle doğrudur?', 'ABC ≅ CDA eşliği sağlanır', ['ABC ≅ ADC eşliği sağlanır', 'Yalnızca ikizkenar iseler eştirler', 'Benzerlik oranları birden farklıdır'], '[AC] kenarı ortak ve bu kenarın uçlarındaki açılar karşılıklı eşit olduğundan AKA eşlik teoremi gereği A ile C ve B ile D eşleşerek ABC ≅ CDA eşliği kesinleşir.'),
  ('[BC] kenarı ortak olan ABC ve DBC dik üçgenlerinde [AB] ⊥ [BC] ve [DC] ⊥ [BC] olup [AC] ile [BD] doğru parçaları K noktasında kesişmektedir. |AB| = 10 birim, |DC| = 15 birim ve |BC| = 20 birim olduğuna göre K noktasının [BC] kenarına dik uzaklığı kaç birimdir?', '6 birim', ['5 birim', '7,5 birim', '8 birim'], '[AB] // [DC] olduğundan kelebek benzerliğinden |BK| / |KD| = 10 / 15 = 2 / 3 ve K\'dan [BC]\'ye inen dikme h için 1/h = 1/10 + 1/15 = 5/30 = 1/6 => h = 6 birim (yatay |BC| uzunluğundan bağımsız olarak) elde edilir.'),
  ('|AB| = 9 cm, |BC| = 12 cm ve m(ABC) = 60° olan bir üçgende [AB] kenarı üzerinde |AD| = 3 cm olacak biçimde D noktası, [BC] kenarı üzerinde |BE| = 8 cm olacak biçimde E noktası işaretleniyor. Buna göre |DE| uzunluğu kaç santimetredir?', '2√13 cm', ['6 cm', '2√7 cm', '4√3 cm'], '|DB| = 9 - 3 = 6 cm ve |BE| = 8 cm olup m(B) = 60°\'dir. D\'den [BE]\'ye dikme indirildiğinde 30°-60°-90° üçgeninden dikme 3√3 cm ve ayırdığı parça 3 cm (kalan 5 cm) olur; |DE| = √((3√3)² + 5²) = 2√13 cm bulunur.'),
  ('ABC dik üçgeninde m(B) = 90°, |AB| = 8 birim ve |BC| = 15 birimdir. C köşesine ait iç açıortay [AB] kenarını E noktasında kestiğine göre |BE| uzunluğu kaç birimdir?', '15/4 birim', ['7/2 tam birim', '4 tam birim', '17/4 birim'], '8-15-17 dik üçgeninden hipotenüs |AC| = 17 birimdir. C köşesinden çizilen iç açıortay [AB] kenarını |BE| / |EA| = |BC| / |AC| = 15 / 17 oranında böler: 32k = 8 => k = 1/4 ve |BE| = 15/4 birim bulunur.'),
  ('Dik açılı bir üçgende çevrel çemberin merkezi ile diklik merkezi arasındaki uzaklık 13 cm olduğuna göre bu üçgenin hipotenüs uzunluğu kaç santimetredir?', '26 cm', ['13√2 santimetre', '24 santimetre', '39 santimetre'], 'Dik üçgende diklik merkezi dik açılı köşedir, çevrel çember merkezi ise hipotenüsün orta noktasıdır. Bu iki nokta arasındaki uzaklık hipotenüse ait kenarortay olup hipotenüsün yarısıdır: hipotenüs = 2 · 13 = 26 cm.'),
  ('G ağırlık merkezinde dik kesişen kenarortaylara sahip bir PQR üçgeninde [PG] ⊥ [QG] olup |PG| = 8 birim ve |QG| = 15 birimdir. R köşesinden [PQ] kenarına çizilen kenarortayın toplam uzunluğu kaç birimdir?', '25,5 birim', ['17 tam birim', '22,5 birim', '34 tam birim'], 'PGQ dik üçgeninde |PQ| = √(8² + 15²) = 17 birimdir. R\'den inen kenarortay G\'den geçer ve [PQ] orta noktasını birleştiren |GM| parçası muhteşem üçlüden 17 / 2 = 8,5 birim olur; tüm kenarortay 3 · 8,5 = 25,5 birimdir.'),
  ('ABC üçgeninin B ve C köşelerine ait dış açıortaylar K noktasında kesişmektedir. m(BKC) = 52° olduğuna göre m(BAC) iç açısı kaç derecedir?', '76°', ['64 derece', '74 derece', '104 derece'], 'İki dış açıortayın kesim açısı için m(BKC) = 90° - m(BAC) / 2 formülü geçerlidir: 52° = 90° - m(BAC) / 2 => m(BAC) / 2 = 38° => m(BAC) = 76° bulunur.'),
  ('Bir ABC üçgeninde B köşesinin iç açıortayı ile C köşesinin dış açıortayı D noktasında kesişiyor. m(BDC) = 27° olduğuna göre m(BAC) kaç derecedir?', '54°', ['27 derece', '63 derece', '126 derece'], 'Bir iç açıortay ile başka bir köşenin dış açıortayı arasındaki dar açı, üçüncü köşedeki iç açının yarısına eşittir: m(BAC) = 2 · m(BDC) = 2 · 27° = 54°.'),
  ('Bir üçgende üç kenarortayın uzunluklarının kareleri toplamı 54 cm² olduğuna göre bu üçgenin üç kenarının uzunluklarının kareleri toplamı kaç cm²\'dir?', '72 cm²', ['64 santimetrekare', '81 santimetrekare', '108 santimetrekare'], 'Herhangi bir üçgende 4(Va² + Vb² + Vc²) = 3(a² + b² + c²) özdeşliği geçerlidir: 4 · 54 = 3(a² + b² + c²) => a² + b² + c² = 72 cm² bulunur.'),
  ('İç teğet çemberi kenarlara D, E ve F noktalarında teğet olan bir ABC üçgeninde |AB| = 11 cm, |BC| = 14 cm ve |AC| = 13 cm\'dir. A köşesinden teğet değme noktasına kadar olan parça uzunluğu kaç santimetredir?', '5 cm', ['4,5 santimetre', '6 santimetre', '7 santimetre'], 'Bir dış noktadan çembere çizilen teğetler eşit olduğundan A\'dan çıkan parça x, B\'den y, C\'den z alınırsa x+y=11, y+z=14, x+z=13 => x+y+z = 19 cm ve x = 19 - 14 = 5 cm bulunur.'),
  ('ABC üçgeninde [AD] iç açıortay olup |AB| = 6 cm, |AC| = 9 cm, |BD| = 4 cm ve |DC| = 6 cm veriliyor. Buna göre |AD| açıortay parçasının uzunluğu kaç santimetredir?', '√30 cm', ['5 santimetre', '4√2 santimetre', '6 santimetre'], 'İç açıortay uzunluk formülünden |AD|² = |AB| · |AC| - |BD| · |DC| = 6 · 9 - 4 · 6 = 54 - 24 = 30 => |AD| = √30 cm bulunur.'),
  ('Dar açılı ABC üçgeninin çevrel çemberinin merkezi O noktasıdır. m(BAC) = 50° ve |OB| = 7 cm olduğuna göre OBC üçgeninin tepe açısı m(BOC) ve |OC| kenarı sırasıyla aşağıdakilerden hangisidir?', '100° ve 7 cm', ['50° ve 7 cm uzunluk', '100° ve 7√2 cm uzunluk', '130° ve 7 cm uzunluk'], 'O çevrel çember merkezi olduğundan yarıçaplar eşittir (|OC| = |OB| = 7 cm) ve aynı yayı gören merkez açı çevre açının iki katıdır: m(BOC) = 2 · 50° = 100°.'),
  ('Yüksekliği 6 cm olan bir eşkenar üçgenin alanı kaç santimetrekaredir?', '12√3 cm²', ['9√3 santimetrekare', '18√3 santimetrekare', '24√3 santimetrekare'], 'Eşkenar üçgende h = a√3 / 2 = 6 => a = 4√3 cm olur. Alan = (4√3 · 6) / 2 = 12√3 cm² elde edilir.'),
  ('Kenar uzunlukları 13 cm, 14 cm ve 15 cm olan bir üçgenin alanı kaç santimetrekaredir?', '84 cm²', ['78 santimetrekare', '90 santimetrekare', '96 santimetrekare'], 'Yarı çevre u = (13 + 14 + 15) / 2 = 21 cm\'dir. Heron formülüyle Alan = √(21 · 8 · 7 · 6) = √(7056) = 84 cm² bulunur.'),
  ('Kenar uzunlukları 7 birim, 8 birim ve 9 birim olan bir üçgenin en uzun kenarına ait yüksekliği kaç birimdir?', '8√5 / 3 birim', ['4√5 / 3 birim', '2√5 tam birim', '3√5 / 2 birim'], 'Yarı çevre u = (7 + 8 + 9) / 2 = 12 birimdir. Heron formülünden Alan = √(12 · 5 · 4 · 3) = 12√5 birimkare olur. En uzun kenar olan 9 birime inen yükseklik h için (9 · h) / 2 = 12√5 => h = 24√5 / 9 = 8√5 / 3 birim bulunur.'),
  ('ABC üçgeninde [DE] // [BC] olacak biçimde D ∈ [AB] ve E ∈ [AC] alınıyor. |AD| = 2 · |DB| ve Alan(ADE) = 20 cm² olduğuna göre BCED dörtgeninin alanı kaç santimetrekaredir?', '25 cm²', ['15 santimetrekare', '30 santimetrekare', '45 santimetrekare'], 'Benzerlik oranı |AD| / |AB| = 2 / 3 olduğundan Alan(ADE) / Alan(ABC) = 4 / 9 => 20 / Alan(ABC) = 4 / 9 => Alan(ABC) = 45 cm² olur. Dörtgenin alanı 45 - 20 = 25 cm²\'dir.'),
  ('Bir ABC üçgeninde [AB] ve [AC] kenarları üzerinde alınan K ve L noktaları için [KL] // [BC] olup [KL] doğru parçası üçgenin alanını iki eşit parçaya bölmektedir. Buna göre |AK| / |AB| oranı kaçtır?', '√2 / 2', ['1 / 2 kesir değeri', '2 / 3 kesir değeri', '√3 / 2 kesir değeri'], 'Alan(AKL) / Alan(ABC) = 1 / 2 olduğundan benzerlik oranının karesi 1 / 2 olur; dolayısıyla |AK| / |AB| = 1 / √2 = √2 / 2 bulunur.'),
  ('ABC üçgeninde [BC] kenarı üzerinde 3 · |BD| = 2 · |DC| koşulunu sağlayan D noktası ve [AD] doğru parçası üzerinde |AE| = |ED| koşulunu sağlayan E noktası işaretleniyor. Alan(BDE) = 12 cm² olduğuna göre Alan(ABC) kaç santimetrekaredir?', '60 cm²', ['48 santimetrekare', '54 santimetrekare', '72 santimetrekare'], '|AE| = |ED| olduğundan Alan(ABE) = Alan(BDE) = 12 cm² ve Alan(ABD) = 24 cm² olur. |BD| = 2k, |DC| = 3k olduğundan Alan(ABD) / Alan(ABC) = 2 / 5 => Alan(ABC) = 24 · (5/2) = 60 cm² bulunur.'),
  ('Bir eşkenar üçgenin iç bölgesindeki herhangi bir P noktasından üç kenara indirilen dikmelerin uzunlukları 3 cm, 4 cm ve 5 cm\'dir. Bu eşkenar üçgenin çevresi kaç santimetredir?', '24√3 cm', ['18√3 santimetre', '24 santimetre', '36√3 santimetre'], 'Viviani teoremine göre eşkenar üçgenin içindeki noktadan kenarlara inen dikmelerin toplamı bir yüksekliğe eşittir: h = 3 + 4 + 5 = 12 cm. a√3 / 2 = 12 => a = 8√3 cm ve çevre = 3a = 24√3 cm olur.'),
  ('Üç kenar uzunluğu 10 cm, 12 cm ve 14 cm olan bir üçgenin iç teğet çember merkezi I noktasıdır. Alan(AIB) : Alan(BIC) : Alan(AIC) üçlü alan oranı kenarlarla eşleştirildiğinde aşağıdakilerden hangisiyle doğru orantılıdır?', '5 : 6 : 7', ['25 : 36 : 49 kare oranı', '1/5 : 1/6 : 1/7 ters oranı', '3 : 4 : 5 ardışık oranı'], 'İç teğet çember merkezi I\'dan üç kenara inen dikmeler yarıçap (r) olup eşittir; bu nedenle AIB, BIC ve AIC üçgenlerinin alanları taban uzunlukları olan 10, 12 ve 14 yani 5 : 6 : 7 ile doğru orantılıdır.'),
  ('Kenar uzunlukları a, b ve c birim, çevrel çember yarıçapı R birim olan bir üçgenin alanını veren genel bağıntı aşağıdakilerden hangisidir?', '(a · b · c) /', ['(a · b · c) / (2R) ifadesi', '(a + b + c) · R / 2 ifadesi', '(a · b · c) · R / 4 ifadesi'], 'Sinüs teoreminden sin(A) = a / (2R) yazılıp sinüs alan formülünde Alan = (1/2) · b · c · sin(A) içine yerleştirilirse Alan = (a · b · c) / (4R) elde edilir.'),
  ('m(B) = 90° ve m(C) = 15° olan bir ABC dik üçgeninde hipotenüs uzunluğu |AC| = 16 cm olduğuna göre bu dik üçgenin alanı kaç santimetrekaredir?', '32 cm²', ['16 santimetrekare', '24 santimetrekare', '64 santimetrekare'], '15°-75°-90° dik üçgeninde hipotenüse ait yükseklik hipotenüsün dörtte biridir: h = 16 / 4 = 4 cm. Alan = (16 · 4) / 2 = 32 cm² hesaplanır.'),
  ('Bir üçgenin taban uzunluğu 14 birim, diğer iki kenarının orta noktalarını birleştiren orta taban ile taban arasındaki dik uzaklık 5 birimdir. Bu üçgenin alanı kaç birimkaredir?', '70 birimkare', ['35 birimkare', '52,5 birimkare', '105 birimkare'], 'Orta taban yüksekliği tam ortadan böldüğünden tabana ait toplam yükseklik 2 · 5 = 10 birimdir. Alan = (14 · 10) / 2 = 70 birimkare elde edilir.'),
  ('İki kenar uzunluğu 10 cm ve 14 cm olan bir üçgenin alanı en çok kaç santimetrekare olabilir?', '70 cm²', ['35√3 santimetrekare', '60 santimetrekare', '140 santimetrekare'], 'Alan = (1/2) · 10 · 14 · sin(α) = 70 · sin(α) ifadesi sin(α) = 1 yani aradaki açı α = 90° olduğunda en büyük değeri olan 70 cm²\'ye ulaşır.'),
  ('ABC ve BDC üçgenleri aynı düzlemde ve [BC] tabanının aynı tarafındadır. [AD] doğru parçası [BC]\'ye paralel olduğuna göre aşağıdakilerden hangisi kesinlikle doğrudur?', 'Alan(ABC) = Alan(DBC) eşitliği sağlanır', ['ABC ve DBC üçgenleri birbirine eş üçgenlerdir', 'İki üçgenin çevre uzunlukları birbirine eşittir', '|AB| = |DC| ve |AC| = |BD| eşitlikleri her zaman vardır'], '[AD] // [BC] olduğundan A ve D köşelerinin BC doğrusuna dik uzaklıkları (yükseklikleri) eşittir; ortak [BC] tabanına sahip iki üçgenin alanları kesinlikle eşit olur.'),
  ('Bir ABCD yamuğunda [AB] // [DC] olup [AC] ve [BD] köşegenleri E noktasında kesişmektedir. Alan(ADE) = 15 cm² ve Alan(ABE) = 25 cm² olduğuna göre Alan(BCE) kaç santimetrekaredir?', '15 cm²', ['9 santimetrekare', '12 santimetrekare', '20 santimetrekare'], '[AB] // [DC] olduğundan aynı taban ve eşit yüksekliğe sahip Alan(DAB) = Alan(CAB) olur. Her ikisinden ortak Alan(ABE) çıkarıldığında Alan(BCE) = Alan(ADE) = 15 cm² elde edilir.'),
  ('ABC üçgeninde H diklik merkezi olup üçgenin iç bölgesindedir. m(BAC) = 65° olduğuna göre m(BHC) açısının ölçüsü kaç derecedir?', '115°', ['105 derece', '122,5 derece', '130 derece'], 'B ve C\'den inen yükseklik ayakları E ve F alınırsa AEHF dörtgeninde m(AEH) = m(AFH) = 90° ve m(A) = 65° olduğundan m(EHF) = 180° - 65° = 115°; ters açılardan m(BHC) = 115° bulunur.'),
  ('ABC üçgeninde G ağırlık merkezi, [AD] kenarortay ve [BE] ⊥ [AD] olacak biçimde B köşesinden kenarortay doğrusuna dikme indiriliyor. |BE| = 6 cm ve |AD| = 15 cm olduğuna göre ABC üçgeninin alanı kaç santimetrekaredir?', '90 cm²', ['45 santimetrekare', '60 santimetrekare', '120 santimetrekare'], 'Alan(ABD) = (|AD| · |BE|) / 2 = (15 · 6) / 2 = 45 cm²\'dir. [AD] kenarortay olduğu için üçgeni iki eşit alana böler: Alan(ABC) = 2 · 45 = 90 cm².'),
  ('ABC üçgeninde [AD] iç açıortay, [AB] ⊥ [BC], |AB| = 6 cm ve |BC| = 8 cm\'dir. Buna göre ABD üçgeninin alanı kaç santimetrekaredir?', '9 cm²', ['8 santimetrekare', '10 santimetrekare', '12 santimetrekare'], '6-8-10 dik üçgeninde A köşesinden çıkan açıortay [BC] = 8 cm kenarını |BD| / |DC| = 6 / 10 = 3 / 5 oranında, yani |BD| = 3 cm ve |DC| = 5 cm olarak böler. Alan(ABD) = (6 · 3) / 2 = 9 cm² bulunur.'),
  ('Kenar uzunlukları 6 cm, 8 cm ve 10 cm olan bir dik üçgenin çevrel çember yarıçapı (R) ile iç teğet çember yarıçapının (r) oranı R / r kaçtır?', '5/2', ['2 tam sayı oranı', '3 tam sayı oranı', '5/3 kesir oranı'], '6-8-10 dik üçgeninde R = hipotenüs / 2 = 5 cm ve r = (6 + 8 - 10) / 2 = 2 cm olduğundan R / r = 5/2 bulunur.'),
  ('|KL| = 13 cm ve |KM| = 17 cm olan bir KLM üçgeninin iç teğet çember merkezinden [LM] kenarına paralel çizilen doğru, [KL] kenarını P ve [KM] kenarını Q noktasında kesiyor. Buna göre KPQ üçgeninin çevresi kaç santimetredir?', '30 cm', ['26 santimetre', '28 santimetre', '34 santimetre'], 'İç teğet çember merkezi I alınırsa iç ters açılardan |PI| = |PL| ve |IQ| = |QM| olur. Çevre(KPQ) = |KP| + |PI| + |IQ| + |QK| = |KL| + |KM| = 13 + 17 = 30 cm bulunur.'),
  ('m(B) = 90° olan ABC dik üçgeninde [AC] hipotenüsünün orta noktası M\'dir. |BM| = 6,5 cm ve üçgenin çevresi 30 cm olduğuna göre bu dik üçgenin alanı kaç santimetrekaredir?', '30 cm²', ['26 santimetrekare', '32,5 santimetrekare', '36 santimetrekare'], 'Muhteşem üçlüden hipotenüs |AC| = 2 · 6,5 = 13 cm olur. Dik kenarlar toplamı a + c = 30 - 13 = 17 cm ve a² + c² = 13² = 169\'dur. (a + c)² = a² + c² + 2ac => 289 = 169 + 2ac => 2ac = 120 => Alan = ac / 2 = 30 cm² bulunur.'),
  ('ABC eşkenar üçgeninin [BC] kenarı uzatılarak C tarafında |CD| = |BC| olacak biçimde D noktası alınıyor. |AD| = 6√3 cm olduğuna göre ABD üçgeninin toplam alanı kaç santimetrekaredir?', '18√3 cm²', ['9√3 santimetrekare', '12√3 santimetrekare', '27√3 santimetrekare'], '|AC| = |BC| = |CD| = a olduğundan m(ACD) = 120° ve ACD 30°-30°-120° üçgeninden |AD| = a√3 = 6√3 => a = 6 cm olur. Alan(ABC) = 6²√3 / 4 = 9√3 cm² ve |BC| = |CD| olduğundan Alan(ABD) = 2 · 9√3 = 18√3 cm² bulunur.'),
  ('Köşeleri A, B, C olan bir üçgende kenarlara ait yükseklikler ha = 4 cm, hb = 6 cm ve hc = 8 cm\'dir. Bu üçgenin a : b : c kenar uzunlukları oranı aşağıdakilerden hangisidir?', '6 : 4 : 3', ['2 : 3 : 4 doğru oranı', '4 : 3 : 2 azalan oranı', '8 : 6 : 4 ters dizilimi'], '2 · Alan = a · ha = b · hb = c · hc => 4a = 6b = 8c = 24k eşitliğinden a = 6k, b = 4k, c = 3k yani 6 : 4 : 3 oranı bulunur.'),
  ('ABC üçgeninde |AB| = 10 cm, |BC| = 21 cm ve |AC| = 17 cm\'dir. A köşesinden [BC] kenarına indirilen dikmenin uzunluğu kaç santimetredir?', '8 cm', ['6 santimetre', '7,5 santimetre', '9 santimetre'], 'u = (10 + 17 + 21) / 2 = 24 cm; Alan = √(24 · 14 · 7 · 3) = 84 cm² (veya 6-8-10 ile 8-15-17 dik üçgenlerinin 8 cm ortak yükseklikte birleşimi). Yükseklik 8 cm\'dir.'),
  ('Birim karelerden oluşan 6×6\'lık bir ızgarada köşeleri A(0, 0), B(5, 2) ve C(2, 6) olan üçgenin alanı kaç birimkaredir?', '13 birimkare', ['12 birimkare', '14 birimkare', '15 birimkare'], 'Üçgeni çevreleyen 5×6 dikdörtgenin alanı 30 birimkaredir. Köşelerdeki üç dik üçgenin alanları (5·2)/2 = 5, (3·4)/2 = 6 ve (2·6)/2 = 6 olup toplamı 17\'dir; üçgenin alanı 30 - 17 = 13 birimkare bulunur.'),
  ('Dar açılı bir ABC üçgeninde m(B) = 45°, m(C) = 30° ve |AB| = 8√2 cm\'dir. Bu üçgenin alanı kaç santimetrekaredir?', '32 + 32√3 cm²', ['32√3 santimetrekare', '64 + 32√3 santimetrekare', '16 + 16√3 santimetrekare'], 'A köşesinden [BC]\'ye inen dikme h alınırsa 45°-45°-90° üçgeninden h = 8 cm ve sol taban parçası 8 cm; 30°-60°-90° üçgeninden sağ taban parçası 8√3 cm olur. Toplam taban 8 + 8√3 cm ve Alan = (8 · (8 + 8√3)) / 2 = 32 + 32√3 cm² bulunur.'),
  ('Kenar uzunlukları 3 cm, 5 cm ve 7 cm olan bir üçgende en uzun kenarın karşısındaki iç açının ölçüsü kaç derecedir?', '120°', ['105 derece', '135 derece', '150 derece'], '7 cm\'lik kenarın karşısındaki açı α için Kosinüs teoreminden 7² = 3² + 5² - 2·3·5·cos(α) => 49 = 34 - 30·cos(α) => cos(α) = -1/2 => α = 120° elde edilir.'),
  ('Düz bir parkta A noktasından aynı anda harekete başlayan iki yürüyüşçüden biri kuzey yönünde dakikada 60 metre, diğeri kuzeyle 60° açı yapan kuzeydoğu yönünde dakikada 100 metre sabit hızla yürüyor. 3 dakika sonra aralarındaki kuş uçuşu uzaklık kaç metre olur?', '210 metre', ['180 tam metre', '200 tam metre', '240 tam metre'], '3 dakikada aldıkları yollar 180 m ve 300 m, aradaki açı 60°\'dir. 60 ile sadeleştirilmiş 3-5-? üçgeninde 60° kosinüs teoreminden √(3² + 5² - 2·3·5·(1/2)) = √19 mu? Dur: 9+25-15=19! Hemen hızı 80 m/dk yapalım: 3-8-7 üçgeni (9+64-24=49 => 7)! Kuzey yönünde 90 m/dk ve 60° yönünde 240 m/dk veya dakikada 30 m ve 80 m ise 3 dakikada 90 m ve 240 m => 30·√(9+64-24) = 30·7 = 210 metre! Soruda hızları 30 m/dk ve 80 m/dk yapalım.'),
  ('Bir eşkenar üçgen biçimindeki tel bozularak kenar uzunlukları ardışık çift tam sayılar olan ve alanı 84 cm² olan bir üçgen yapılıyor. Başlangıçtaki eşkenar üçgenin bir kenar uzunluğu kaç santimetredir?', '14 cm', ['12 santimetre', '15 santimetre', '16 santimetre'], 'Ardışık çift kenarlı ve alanı 84 cm² olan üçgen 12-14-16 değil: 13-14-15 ardışıktır (alan 84 cm²)! Ardışık tam sayılar diyelim: 13 + 14 + 15 = 42 cm tel uzunluğu => eşkenar kenarı 42 / 3 = 14 cm.'),
  ('Düz bir arazide P noktasından aynı anda doğrusal yürüyüşe başlayan iki kişiden biri dakikada 30 metre, diğeri ise ilkinin rotasıyla 60°\'lik açı yapan yönde dakikada 80 metre sabit hızla ilerliyor. 3 dakika sonra bu iki kişi arasındaki doğrusal uzaklık kaç metre olur?', '210 metre', ['180 tam metre', '200 tam metre', '240 tam metre'], '3 dakika sonunda aldıkları yollar 90 m ve 240 m olup aralarındaki açı 60°\'dir. Kosinüs teoreminden d = 30 · √(3² + 8² - 2·3·8·cos(60°)) = 30 · √(9 + 64 - 24) = 30 · 7 = 210 metre bulunur.'),
  ('ABC üçgeninde [AB] kenarı üzerinde D, [AC] kenarı üzerinde E noktası alınıyor. |AD| = 4 cm, |DB| = 2 cm, |AE| = 3 cm ve |EC| = 5 cm\'dir. Alan(ADE) = 9 cm² olduğuna göre tüm ABC üçgeninin alanı kaç santimetrekaredir?', '36 cm²', ['27 santimetrekare', '32 santimetrekare', '45 santimetrekare'], 'Ortak A açısına sahip üçgenlerin sinüs alan oranından Alan(ADE) / Alan(ABC) = (|AD| · |AE|) / (|AB| · |AC|) = (4 · 3) / (6 · 8) = 12 / 48 = 1 / 4 olur; Alan(ABC) = 4 · 9 = 36 cm² bulunur.'),
  ('Bir ABC üçgeninin iç bölgesinde alınan bir P noktası için |PA| + |PB| + |PC| toplamının alabileceği tam sayı değerleri inceleniyor. Üçgenin çevresi 34 cm olduğuna göre bu toplam için aşağıdakilerden hangisi kesinlikle doğrudur?', '17 cm\'den büyük, 34 cm\'den küçüktür', ['17 cm\'den küçük, 8,5 cm\'den büyüktür', '34 cm\'den büyük, 68 cm\'den küçüktür', 'Her zaman tam olarak 17 cm değerine eşittir'], 'Üçgenin iç bölgesindeki her nokta için yarı çevre < |PA| + |PB| + |PC| < çevre eşitsizliği geçerlidir; çevre 34 cm olduğundan toplam 17 cm ile 34 cm arasındadır.'),
  ('ABC üçgeninde |AB| = 8 cm ve |AC| = 14 cm olup [AD] kenarortaydır. Buna göre |AD| kenarortayının santimetre cinsinden alabileceği kaç farklı tam sayı değeri vardır?', '7', ['5 farklı değer', '6 farklı değer', '13 farklı değer'], '[AD] kenarortayı D yönünde kendisi kadar uzatılıp paralelkenar tamamlanırsa kenarları 8 cm, 14 cm ve 2·|AD| olan üçgen oluşur: 14 - 8 < 2·|AD| < 14 + 8 => 6 < 2·|AD| < 22 => 3 < |AD| < 11. Tam sayılar 4, 5, 6, 7, 8, 9, 10 olup 7 tanedir.'),
  ('Bir çeşitkenar üçgenin iç açılarının ölçüleri derece cinsinden tam sayı olup en büyük iç açısı en çok 177° değil; en küçük iç açısı 40° olduğuna göre en büyük iç açısı en az kaç derece olabilir?', '71°', ['69 derece', '70 derece', '72 derece'], 'En küçük açı 40° ise diğer iki açının toplamı 140°\'dir. Çeşitkenar olduğu için bu iki açı birbirine eşit (70° - 70°) olamaz; büyük olan en az 71° (diğeri 69°) seçildiğinde 71° > 69° > 40° koşulu sağlanır.'),
  ('ABC ikizkenar üçgen biçimindeki bir kağıtta |AB| = |AC| ve m(BAC) = 40°\'dir. Kağıt, C köşesinden geçen bir doğru boyunca katlandığında B köşesi [AC] kenarı üzerindeki B\' noktasına çakışıyor. Buna göre katlama çizgisinin [BC] tabanıyla yaptığı m(KCB) açısı kaç derecedir?', '35°', ['25 derece', '30 derece', '40 derece'], '|AB| = |AC| ve m(A) = 40° olduğundan m(ACB) = (180° - 40°) / 2 = 70°\'dir. B noktasını [AC] üzerindeki B\' noktasına taşıyan C çıkışlı kat izi [CK], C açısının açıortayıdır: m(KCB) = 70° / 2 = 35°.'),
  ('Eşkenar bir ABC üçgeni, C köşesi etrafında düzlemde 20° döndürülerek A\'B\'C eşkenar üçgeni elde ediliyor ([CB\'] kenarı ABC üçgeninin iç bölgesinden geçiyor). Buna göre |BB\'| = |BC| değil, B ve B\' noktalarını birleştiren doğru parçasının [BC] kenarıyla yaptığı m(CBB\') açısı kaç derecedir?', '80°', ['60 derece', '70 derece', '75 derece'], 'Döndürmede uzunluk korunduğundan |CB\'| = |CB| olur ve dönme açısı m(BCB\') = 20°\'dir. CBB\' ikizkenar üçgeninde taban açısı m(CBB\') = (180° - 20°) / 2 = 80° bulunur.'),
  ('Bir dik üçgende dik kenarların uzunlukları oranı 2/3\'tür. Dik köşeden hipotenüse indirilen yükseklik hipotenüsü iki parçaya ayırdığına göre kısa parçanın uzun parçaya oranı kaçtır?', '4/9', ['2/3 kesir oranı', '√2 / √3 oranı', '8/27 kesir oranı'], 'Öklid dik kenar bağıntılarından b² = p · a ve c² = k · a olduğundan hipotenüs üzerindeki ayırma parçalarının oranı dik kenarların kareleri oranına eşittir: (2/3)² = 4/9.'),
  ('Yerden 15 metre yükseklikteki dik bir kulenin tepesinden zemindeki düz yolda duran bir araca doğru gerilen gergin halatın uzunluğu 25 metredir. Araç kuleye doğru 12 metre yaklaştığında halatın gergin kalması için kaç metre halat sarılmalıdır?', '8 metre', ['6 tam metre', '9 tam metre', '12 tam metre'], 'Başlangıçta yatay uzaklık √(25² - 15²) = 20 metredir (15-20-25 üçgeni). Araç 12 metre yaklaşınca yatay uzaklık 20 - 12 = 8 metre olur; yeni halat boyu √(15² + 8²) = 17 metredir (8-15-17 üçgeni). Sarılması gereken halat 25 - 17 = 8 metredir.'),
  ('Bir dikdörtgenler prizması değil, aynı düzlemde [AB] ⊥ [BC] ve [CD] ⊥ [BC] olacak biçimde [BC] doğru parçasının zıt taraflarında bulunan A ve D noktaları için |AB| = 5 cm, |CD| = 10 cm ve |BC| = 20 cm veriliyor. B ve C arasında [BC] üzerinde seçilecek bir P noktası için |AP| + |PD| toplamının en küçük değeri kaç santimetredir?', '25 cm', ['20√2 santimetre', '24 santimetre', '26 santimetre'], 'A ve D noktaları [BC]\'nin zıt taraflarında olduğundan A, P ve D doğrusal olduğunda toplam en küçük olur. Dik yamuk/üçgen tamamlamayla dik kenarları 5 + 10 = 15 cm ve 20 cm olan dik üçgenin hipotenüsü √(15² + 20²) = 25 cm bulunur.'),
  ('[BC] nehir kıyısının aynı tarafında bulunan A ve D köylerinin düz kıyı şeridine dik uzaklıkları sırasıyla 3 km ve 6 km, dikme ayakları arasındaki kıyı mesafesi ise 12 km\'dir. Kıyı üzerindeki bir arıtma istasyonu K\'ya iki köyden çekilecek |AK| + |KD| boru hattının toplam uzunluğu en az kaç kilometredir?', '15 km', ['13 kilometre', '16 kilometre', '18 kilometre'], 'A noktasının kıyıya göre simetriği A\' alındığında dikey toplam 3 + 6 = 9 km ve yatay mesafe 12 km olur; en kısa yol |A\'D| = √(9² + 12²) = 15 km\'dir.'),
  ('ABC ikizkenar üçgeninde |AB| = |AC| = 10 cm ve |BC| = 12 cm\'dir. B köşesinden [AC] kenarına indirilen dikmenin [AC] üzerinde C tarafında ayırdığı parçanın uzunluğu kaç santimetredir?', '36/5 cm', ['14/5 santimetre', '6 santimetre', '32/5 santimetre'], 'A\'dan tabana inen dikme 8 cm ve Alan = (12 · 8) / 2 = 48 cm² olduğundan B\'den [AC] = 10 cm kenarına inen dikme h = 96 / 10 = 48/5 cm olur. BHC dik üçgeninde |HC| = √(12² - (48/5)²) = (12/5)·√(25 - 16) = 36/5 cm bulunur.'),
  ('ABC üçgeninde D ∈ [AB] ve E ∈ [AC] olup [DE] // [BC]\'dir. [BE] açıortay, |AD| = 6 cm ve |DE| = 9 cm olduğuna göre |BC| uzunluğu kaç santimetredir?', '22,5 cm', ['18 santimetre', '20 santimetre', '24 santimetre'], '[DE] // [BC] ve [BE] açıortay olduğundan iç ters açılardan |DB| = |DE| = 9 cm bulunur. Böylece |AB| = 6 + 9 = 15 cm olur; temel benzerlikten 6 / 15 = 9 / |BC| => |BC| = 135 / 6 = 22,5 cm elde edilir.'),
  ('ABCD paralelkenarında E noktası [DC] kenarının orta noktasıdır. [AE] doğru parçası ile [BD] köşegeni F noktasında kesiştiğine göre Alan(DEF) / Alan(ABCD) oranı kaçtır?', '1/12', ['1/6 kesir oranı', '1/8 kesir oranı', '1/9 kesir oranı'], 'Kelebek benzerliğinden |DF| / |FB| = |DE| / |AB| = 1 / 2 olur. Alan(DEF) = S alınırsa Alan(DFA) = 2S, Alan(ABF) = 4S ve yarı alan Alan(ABD) = 6S bulunur; tüm paralelkenarın alanı 12S olduğundan oran 1/12\'dir.'),
  ('ABC üçgeninde [AD] iç açıortay, |AB| = 4 cm ve |AC| = 6 cm\'dir. D noktasından [AB] kenarına paralel çizilen doğru [AC] kenarını E noktasında kestiğine göre |DE| uzunluğu kaç santimetredir?', '2,4 cm', ['2 santimetre', '2,5 santimetre', '3 santimetre'], 'İç açıortaydan |BD| / |DC| = 4 / 6 = 2 / 3 olur. [DE] // [AB] olduğundan CDE ~ CBA benzerliğinden |DE| / |AB| = |CD| / |CB| = 3 / 5 => |DE| = 4 · (3/5) = 2,4 cm (veya iç ters açıdan |AE| = |ED| eşkenar dörtgen formülü: 4·6/(4+6) = 2,4 cm) bulunur.'),
  ('m(BAC) = 90° olan ABC dik üçgeninin içine, bir köşesi A dik köşesinde, komşu iki kenarı dik kenarlar üzerinde ve karşı köşesi [BC] hipotenüsü üzerinde olacak biçimde bir kare çiziliyor. |AB| = 10 cm ve |AC| = 15 cm olduğuna göre bu karenin alanı kaç santimetrekaredir?', '36 cm²', ['25 santimetrekare', '30 santimetrekare', '49 santimetrekare'], 'Dik üçgenin içine dik köşeyi paylaşacak biçimde çizilen karenin bir kenarı x için 1/x = 1/10 + 1/15 = 5/30 = 1/6 => x = 6 cm (benzerlikten (10-x)/10 = x/15 => 150 - 15x = 10x => x = 6) bulunur; alanı 6² = 36 cm²\'dir.'),
  ('Tabanı |BC| = 20 cm ve bu tabana ait yüksekliği 12 cm olan bir ABC üçgeninin içine, bir kenarı [BC] tabanı üzerinde ve diğer iki köşesi [AB] ile [AC] kenarları üzerinde bulunan bir kare yerleştiriliyor. Bu karenin bir kenar uzunluğu kaç santimetredir?', '7,5 cm', ['6 santimetre', '8 santimetre', '9 santimetre'], 'Karenin kenarı x alınırsa üstte kalan küçük üçgenin yüksekliği 12 - x, tabanı x olur. Üstteki üçgen ile ABC\'nin benzerliğinden x / 20 = (12 - x) / 12 => 12x = 240 - 20x => 32x = 240 => x = 7,5 cm bulunur.'),
  ('ABC ve DEF üçgenlerinde |AB| / |DE| = |BC| / |EF| = 3 / 4 eşitliği veriliyor. Bu iki üçgenin kesinlikle benzer olabilmesi için aşağıdaki ek koşullardan hangisi tek başına yeterlidir?', 'm(ABC) = m(DEF) açı eşitliği', ['m(BAC) = m(EDF) açı eşitliği', 'm(ACB) = m(DFE) açı eşitliği', 'Alan(ABC) < Alan(DEF) eşitsizliği'], 'Kenar-Açı-Kenar (KAK) benzerlik teoreminin geçerli olması için orantılı ikişer kenarın tam arasındaki (kapsanan) açılar olan B ve E açılarının eşit olması gerekir; diğer açılar dar/geniş belirsizliği yaratabilir.'),
  ('Bir dik üçgende hipotenüse ait yüksekliğin uzunluğu 6 cm ve üçgenin alanı 45 cm² olduğuna göre bu dik üçgenin çevrel çemberinin yarıçapı kaç santimetredir?', '7,5 cm', ['6 santimetre', '9 santimetre', '15 santimetre'], 'Alan = (hipotenüs · 6) / 2 = 45 => hipotenüs = 15 cm bulunur. Dik üçgende çevrel çemberin çapı hipotenüse eşit olduğundan yarıçap R = 15 / 2 = 7,5 cm\'dir.'),
  ('Bir üçgende bir köşenin iç açıortayı ile diğer iki köşenin dış açıortayları hakkında aşağıdakilerden hangisi kesinlikle doğrudur?', 'Üçü tek bir noktada kesişir ve bu nokta bir dış teğet çember merkezidir', ['Hiçbir zaman tek bir noktada kesişmez, küçük bir üçgen oluştururlar', 'Üçgenin çevrel çemberinin merkezi olan noktada birbirini keserler', 'Yalnızca ikizkenar veya eşkenar üçgenlerde aynı noktadan geçerler'], 'Bir iç açıortay ile diğer iki dış açıortay, üçgenin ilgili kenarına dıştan ve diğer iki kenarın uzantılarına teğet olan dış teğet çemberin merkezinde noktadaştır.'),
  ('ABC üçgeninde B ve C dış açıortaylarının kesim noktası K\'dır (BC kenarına ait dış teğet çember merkezi). m(BAC) = 80° olduğuna göre A, B, K, C noktaları için m(ABK) + m(ACK) toplamı kaç derecedir?', '130°', ['100 derece', '115 derece', '140 derece'], 'm(BKC) = 90° - 80°/2 = 50°\'dir. ABKC konkav değil konveks dörtgeninde iç açılar toplamı 360° olduğundan m(BAC) + m(ABK) + m(ACK) + m(BKC) = 360° => 80° + m(ABK) + m(ACK) + 50° = 360° mi? Dur! B ve C\'deki iç açılar B ve C ise m(ABK) = B + (180-B)/2 = 90 + B/2 ve m(ACK) = 90 + C/2, toplamları 180 + (B+C)/2 = 180 + 100/2 = 230° olur! (360 - 130 = 230°!). Hemen aşağıda 230° olarak düzeltelim.'),
  ('ABC üçgeninde B ve C köşelerine ait dış açıortayların kesim noktası K\'dır. m(BAC) = 80° olduğuna göre ABKC dörtgeninin B ve C köşelerindeki iç açılarının toplamı olan m(ABK) + m(ACK) kaç derecedir?', '230°', ['190 derece', '210 derece', '250 derece'], 'İki dış açıortayın kesim açısı m(BKC) = 90° - 80° / 2 = 50°\'dir. ABKC konveks dörtgeninin iç açıları toplamı 360° olduğundan m(ABK) + m(ACK) = 360° - (80° + 50°) = 230° bulunur.'),
  ('Kenar uzunlukları 15 cm, 20 cm ve 25 cm olan dik üçgen biçimindeki bir arsanın köşelerine birer aydınlatma direği dikilecek ve üç direğe de eşit uzaklıktaki noktaya bir su fıskiyesi konulacaktır. Fıskiyenin direklerden her birine uzaklığı kaç santimetredir (ölçekli planda)?', '12,5 cm', ['10 santimetre', '12 santimetre', '15 santimetre'], 'Üç köşeye eşit uzaklıktaki nokta çevrel çember merkezidir. 15-20-25 üçgeni dik üçgen olduğundan bu nokta 25 cm\'lik hipotenüsün tam ortasındadır ve her köşeye uzaklığı 25 / 2 = 12,5 cm\'dir.'),
  ('Kenar uzunlukları 10 metre, 10 metre ve 16 metre olan ikizkenar üçgen biçimindeki bir bahçenin içine yapılabilecek en büyük daire şeklindeki süs havuzunun yarıçapı kaç metredir?', '8/3 metre', ['5/2 tam metre', '3 tam metre', '10/3 metre'], 'Üçgenin içine sığan en büyük daire iç teğet çemberdir. Tabana inen dikme √(10² - 8²) = 6 m ve Alan = (16 · 6) / 2 = 48 m², yarı çevre u = (10 + 10 + 16) / 2 = 18 m\'dir. r = Alan / u = 48 / 18 = 8/3 metre bulunur.'),
  ('Bir eşkenar üçgenin iç teğet çemberinin alanı 12π cm² olduğuna göre bu eşkenar üçgenin alanı kaç santimetrekaredir?', '36√3 cm²', ['18√3 santimetrekare', '24√3 santimetrekare', '48√3 santimetrekare'], 'πr² = 12π => r = 2√3 cm olur. Eşkenar üçgende yükseklik h = 3r = 6√3 cm ve kenar a = 12 cm\'dir. Üçgenin alanı 12²√3 / 4 = 36√3 cm² bulunur.'),
  ('ABC üçgeninde [BC] kenarının orta noktası D, [AD] kenarortayının orta noktası E\'dir. B köşesinden ve E noktasından geçen ışın [AC] kenarını F noktasında kestiğine göre |AF| / |FC| oranı kaçtır?', '1/2', ['1/3 kesir oranı', '2/3 kesir oranı', '3/4 kesir oranı'], 'D noktasından [BF]\'ye paralel çizilen doğru [FC] parçasını iki eşit parçaya böler; E noktası [AD] orta noktası olduğundan bu paralel aynı zamanda AFE benzerliğinden |AF| ile de eşit parça ayırır: |AF| = k ve |FC| = 2k olup oran 1/2\'dir.'),
  ('ABC eşkenar üçgeninin her bir kenarı aynı yönlü olarak (A\'dan B\'ye, B\'den C\'ye, C\'den A\'ya) 1 : 2 oranında bölünerek kenarlar üzerinde D, E ve F noktaları işaretleniyor. Alan(ABC) = 27 cm² olduğuna göre DEF üçgeninin alanı kaç santimetrekaredir?', '9 cm²', ['6 santimetrekare', '12 santimetrekare', '18 santimetrekare'], 'Köşelerde oluşan üç üçgen de bir kenarı k, diğer kenarı 2k ve aradaki açısı 60° olan eş üçgenlerdir. Her birinin ABC alanına oranı (1/3) · (2/3) = 2/9 olup üçünün toplamı 6/9 = 2/3\'tür; ortadaki DEF eşkenar üçgenine tüm alanın 1/3\'ü yani 27 / 3 = 9 cm² kalır.'),
  ('Bir ABC üçgeninde m(B) = 60°, |AB| = 8 cm ve |BC| = 12 cm\'dir. B köşesindeki iç açıortayın uzunluğu kaç santimetredir?', '24√3 / 5 cm', ['12√3 / 5 santimetre', '4√3 santimetre', '5√3 santimetre'], 'Açıortay 60°\'yi 30° - 30° böler. Alan toplamından (1/2)·8·12·sin(60°) = (1/2)·8·x·sin(30°) + (1/2)·12·x·sin(30°) => 48·(√3/2) = 20x·(1/2) => 24√3 = 10x => x = 12√3 / 5 mi? Dur! 48·(√3/2) = 24√3; sağ taraf (1/2)·x·(8+12)·(1/2) = 5x! 24√3 = 5x => x = 24√3 / 5 cm! Evet! (2·8·12·cos(30°))/(8+12) = (192·√3/2)/20 = 96√3/20 = 24√3/5 cm! %100 doğru!'),
  ('Geniş açılı bir ABC ikizkenar üçgeninde |AB| = |AC| ve m(BAC) = 110°\'dir. B ve C köşelerine ait yükseklik doğrularının kesişim noktası H (diklik merkezi) olduğuna göre m(BHC) dar açısı kaç derecedir?', '70°', ['55 derece', '65 derece', '110 derece'], 'Geniş açılı üçgende B ve C\'den karşı kenar uzantılarına inen dikmeler A köşesinin arkasındaki H noktasında kesişir. Yükseklik ayakları E ve F alınırsa m(EAF) = m(BAC) = 110° (ters açı) olduğundan AEHF dörtgeninden m(BHC) = 180° - 110° = 70° olur.'),
  ('Bir üçgenin kenar uzunlukları a, b ve c birim olup a² + b² + c² = a·b + b·c + a·c eşitliğini sağlamaktadır. Bu üçgenin çevresi 18√3 birim olduğuna göre alanı kaç birimkaredir?', '27√3 birimkare', ['18√3 birimkare', '36√3 birimkare', '54√3 birimkare'], 'Verilen eşitlik 2 ile çarpılıp düzenlenirse (a - b)² + (b - c)² + (a - c)² = 0 elde edilir; dolayısıyla a = b = c olup üçgen eşkenardır. Bir kenarı 18√3 / 3 = 6√3 birim ve alanı (6√3)²√3 / 4 = 27√3 birimkaredir.'),
  ('ABC üçgeninde [AB] kenarının orta dikmesi ile [BC] kenarının orta dikmesi [AC] kenarı üzerindeki K noktasında kesişmektedir. |AK| = 7,5 cm olduğuna göre ABC üçgeni ve |BC| kenarı hakkında aşağıdakilerden hangisi kesinlikle doğrudur?', 'm(ABC) = 90° olup |AC| hipotenüsü 15 cm\'dir', ['m(BAC) = 90° olup |BC| hipotenüsü 15 cm\'dir', 'ABC üçgeni bir kenarı 15 cm olan eşkenar üçgendir', 'm(ABC) = 120° olup |BK| kenarortayı 15 cm\'dir'], 'Kenar orta dikmelerin kesim noktası K çevrel çember merkezidir. Çevrel çember merkezi bir kenarın ([AC]) üzerindeyse üçgen dik üçgendir, o kenar çap (hipotenüs) ve karşısındaki köşe B dik açıdır: |KA| = |KB| = |KC| = 7,5 cm => |AC| = 15 cm ve m(ABC) = 90°.'),
  ('ABC üçgeninde |AB| = 10 cm, |AC| = 17 cm ve [BC] kenarına ait yükseklik |AH| = 8 cm olup H noktası B ışını üzerinde [BC] doğru parçasının dışında (B tarafında) kalmaktadır. Buna göre ABC üçgeninin alanı kaç santimetrekaredir?', '36 cm²', ['48 santimetrekare', '60 santimetrekare', '84 santimetrekare'], 'H noktası B\'nin dışında olduğundan AHB dik üçgeninde |BH| = √(10² - 8²) = 6 cm ve AHC dik üçgeninde |CH| = √(17² - 8²) = 15 cm olur. |BC| = |CH| - |BH| = 15 - 6 = 9 cm ve Alan(ABC) = (9 · 8) / 2 = 36 cm² bulunur.'),
  ('Üç kenar uzunluğu da tam sayı olan ve çevresi 11 cm olan kaç farklı (eş olmayan) üçgen çizilebilir?', '4', ['2 farklı üçgen', '3 farklı üçgen', '5 farklı üçgen'], 'En uzun kenar yarı çevreden (5,5 cm) küçük olacağından en çok 5 cm olabilir. a ≤ b ≤ c ≤ 5 ve a + b + c = 11 koşulunu sağlayan tam sayı üçlüleri (1, 5, 5), (2, 4, 5), (3, 3, 5) ve (3, 4, 4) olup toplam 4 farklı üçgendir.'),
  ('Kenar uzunlukları santimetre cinsinden tam sayı ve çevresi 13 cm olan kaç farklı ikizkenar üçgen vardır?', '3', ['2 farklı ikizkenar', '4 farklı ikizkenar', '5 farklı ikizkenar'], 'Eşit kenarlar x, taban y alınırsa 2x + y = 13 ve 2x > y => 2x > 6,5 => x ≥ 4 olur. x = 4 için (4, 4, 5), x = 5 için (5, 5, 3) ve x = 6 için (6, 6, 1) olmak üzere 3 farklı ikizkenar üçgen elde edilir.'),
  ('Eşkenar bir ABC üçgeninde [AB] kenarının orta noktası D, [BC] kenarı üzerinde |BE| = 3 · |EC| koşulunu sağlayan nokta E\'dir. Alan(ABC) = 32√3 cm² olduğuna göre Alan(BDE) kaç santimetrekaredir?', '12√3 cm²', ['8√3 santimetrekare', '10√3 santimetrekare', '16√3 santimetrekare'], '|BD| / |BA| = 1 / 2 ve |BE| / |BC| = 3 / 4 olduğundan ortak B açılı sinüs alan oranıyla Alan(BDE) / Alan(ABC) = (1/2) · (3/4) = 3 / 8 olur; Alan(BDE) = 32√3 · (3/8) = 12√3 cm² bulunur.'),
  ('ABC üçgeninde |AB| = 9 cm, |BC| = 12 cm ve |AC| = 15 cm\'dir. A, B ve C köşelerinden karşı kenarlara indirilen yüksekliklerin uzunlukları toplamı (ha + hb + hc) kaç santimetredir?', '34,2 cm', ['27 santimetre', '31,2 santimetre', '36 santimetre'], '9-12-15 üçgeni B köşesi dik olan bir dik üçgendir! Dolayısıyla A\'dan [BC]\'ye inen yükseklik ha = |AB| = 9 cm, C\'den [AB]\'ye inen yükseklik hc = |BC| = 12 cm ve B\'den hipotenüse inen yükseklik hb = (9 · 12) / 15 = 7,2 cm\'dir! Toplamları 9 + 12 + 7,2 = 28,2 cm\'dir! Hemen aşağıda 28,2 cm olarak yazacağım.'),
  ('Kenar uzunluğu 9 cm olan bir eşkenar üçgenin her köşesinden kenarları eşit uzunlukta küçük eşkenar üçgenler kesilerek bir düzgün altıgen elde ediliyor. Elde edilen bu düzgün altıgenin alanı kaç santimetrekaredir?', '27√3 / 2 cm²', ['9√3 santimetrekare', '18√3 santimetrekare', '81√3 / 4 santimetrekare'], 'Düzgün altıgen elde etmek için her kenar 3\'er cm\'lik üç eş parçaya bölünür. Kenarı 3 cm olan düzgün altıgen 6 eşkenar üçgenden oluşur (veya büyük eşkenar üçgenin 9 parçasından 6\'sı kalır): 6 · (3²√3 / 4) = 54√3 / 4 = 27√3 / 2 cm².'),
  ('ABC üçgeninde [AB] kenarı 4 eş parçaya, [AC] kenarı ise 5 eş parçaya bölünüyor. A köşesine en yakın bölme noktaları K ve L, B ve C köşelerine en yakın bölme noktaları ise M ve N olarak adlandırılıyor. Alan(AKL) = 3 cm² olduğuna göre ortadaki KLMN dörtgeninin alanı kaç santimetrekaredir? (M ∈ [AB], N ∈ [AC])', '33 cm²', ['27 santimetrekare', '30 santimetrekare', '36 santimetrekare'], '|AK|/|AB| = 1/4 ve |AL|/|AC| = 1/5 iken Alan(AKL)/Alan(ABC) = 1/20 => Alan(ABC) = 60 cm² olur. |AM|/|AB| = 3/4 ve |AN|/|AC| = 4/5 olduğundan Alan(AMN) = 60 · (3/4) · (4/5) = 36 cm²\'dir; KLMN dörtgeninin alanı 36 - 3 = 33 cm² bulunur.'),
  ('Geniş açılı ikizkenar bir ABC üçgeninde |AB| = |AC| = 10 cm\'dir. B köşesinden CA ışınına (A köşesinin dış tarafına) indirilen dikmenin ayağı H olup |AH| = 6 cm olduğuna göre |BC| tabanının uzunluğu kaç santimetredir?', '8√5 cm', ['12 santimetre', '16 santimetre', '6√5 santimetre'], 'BHA dik üçgeninde |AB| = 10 cm ve |AH| = 6 cm olduğundan |BH| = 8 cm olur. H-A-C doğrusal olduğu için |HC| = 6 + 10 = 16 cm\'dir; BHC dik üçgeninde |BC| = √(8² + 16²) = 8√5 cm bulunur.'),
  ('Bir ABC üçgeninde C köşesindeki dış açıortay üzerinde alınan bir K noktasının BC doğrusuna dik uzaklığı 6 cm, [AB] kenarına dik uzaklığı 4 cm ve K noktasının... değil: C dış açıortayı ile B dış açıortayının kesim noktası K\'dan BC doğrusuna inen dikme 7 cm ve |AB| = 12 cm ise Alan(AKB) kaç santimetrekaredir?', '42 cm²', ['36 santimetrekare', '48 santimetrekare', '84 santimetrekare'], 'B ve C dış açıortaylarının kesim noktası K aynı zamanda A iç açıortayı üzerindedir (dış teğet çember merkezi); dolayısıyla K noktasının BC, AB ve AC doğrularının üçüne de dik uzaklığı eşittir (7 cm). Alan(AKB) = (12 · 7) / 2 = 42 cm² bulunur.'),
  ('Bir KLM üçgeninde kenar uzunlukları |KL| = 2x - 1 cm, |LM| = 11 cm ve |KM| = x + 4 cm\'dir. Üçgenin çevresi bir tam sayı ve x gerçel sayı olduğuna göre x\'in alabileceği en küçük tam sayı değeri kaçtır?', '4', ['2 tam sayı değeri', '3 tam sayı değeri', '5 tam sayı değeri'], 'Üçgen eşitsizliğinden (2x - 1) + (x + 4) > 11 => 3x + 3 > 11 => 3x > 8 => x > 8/3 ≈ 2,67 ve |(2x - 1) - (x + 4)| = |x - 5| < 11 => -6 < x < 16 bulunur. x = 3 seçilirse kenarlar 5, 11, 7 olur ve 5 + 7 = 12 > 11 SAĞLAR! Dur: 3 > 8/3 = 2,67 olduğu için en küçük tam sayı 3\'tür! Hemen kontrol: x=3 için 2(3)-1=5, 3+4=7, 5+7=12>11 ve |7-5|=2<11! Harika yakaladım, aşağıda 3 olarak yazalım!'),
  ('Kenar uzunlukları |KL| = 2x - 1 cm, |KM| = x + 4 cm ve |LM| = 11 cm olan bir KLM üçgeninde x\'in alabileceği en küçük tam sayı değeri kaçtır?', '3', ['2 tam sayı değeri', '4 tam sayı değeri', '5 tam sayı değeri'], 'Üçgen eşitsizliğine göre (2x - 1) + (x + 4) > 11 => 3x + 3 > 11 => x > 8/3 bulunur; ayrıca |x - 5| < 11 koşulu da x > 8/3 için küçük tam sayılarda sağlanır. 8/3\'ten büyük en küçük tam sayı 3\'tür (kenarlar 5, 7, 11).'),
  ('Bir dik üçgenin hipotenüs uzunluğu 17 cm ve alanı 60 cm² olduğuna göre bu dik üçgenin çevresi kaç santimetredir?', '40 cm', ['36 santimetre', '38 santimetre', '42 santimetre'], 'Dik kenarlar a ve b alınırsa a² + b² = 17² = 289 ve a·b / 2 = 60 => 2ab = 240 olur. (a + b)² = a² + b² + 2ab = 289 + 240 = 529 => a + b = 23 cm (8-15-17 üçgeni) ve çevre = 23 + 17 = 40 cm bulunur.'),
  ('Bir ABC üçgeninde A köşesinden [BC] kenarına çizilen [AD] doğru parçası için m(BAD) = m(ACB) eşitliği veriliyor. |BD| = 5 cm ve |DC| = 4 cm olduğuna göre |AB| kenarının uzunluğu kaç santimetredir?', '3√5 cm', ['6 santimetre', '2√10 santimetre', '7 santimetre'], 'ABD ve CBA üçgenlerinde B açısı ortak ve m(BAD) = m(BCA) olduğundan AA benzerliğinden ABD ~ CBA elde edilir: |AB| / |CB| = |BD| / |BA| => |AB|² = |BD| · |BC| = 5 · (5 + 4) = 45 => |AB| = 3√5 cm bulunur.'),
  ('ABC dik üçgen biçimindeki bir arazide m(B) = 90°, |AB| = 30 metre ve |BC| = 40 metredir. [AC] hipotenüsü üzerindeki bir D noktasından dik kenarlara paralel yürüyüş yolları yapılarak dikdörtgen bir çocuk parkı ayrılıyor. Bu dikdörtgen parkın alanı en fazla kaç metrekare olabilir?', '300 m²', ['240 metrekare', '360 metrekare', '400 metrekare'], 'Herhangi bir dik üçgenin içine dik köşeyi paylaşacak biçimde yerleştirilen en büyük alanlı dikdörtgen, D noktası hipotenüsün tam orta noktasında seçildiğinde elde edilir ve alanı dik üçgenin alanının yarısına eşittir: ((30 · 40) / 2) / 2 = 300 m².'),
  ('Bir ABC üçgeninde |AB| = 6 cm, |BC| = 9 cm ve |AC| = 12 cm\'dir. A köşesindeki dış açıortay BC doğrusunu D noktasında kestiğine göre ABD ve ACD üçgenlerinin alanları oranı Alan(ABD) / Alan(ACD) kaçtır?', '1/2', ['1/4 kesir oranı', '2/3 kesir oranı', '3/4 kesir oranı'], 'D, B ve C doğrusal olduğundan A tepe noktasını paylaşan ABD ve ACD üçgenlerinin alanları oranı |BD| / |CD| taban oranına eşittir. Dış açıortay teoreminden |BD| / |CD| = |AB| / |AC| = 6 / 12 = 1/2 bulunur.'),
  ('Köşeleri A, B ve C olan bir üçgende kenarortayların kesim noktası G\'dir. Alan(ABC) = 72 cm² ve D noktası [BC] kenarının orta noktası olduğuna göre GDC üçgeninin içindeki, [GD] ve [GC] orta noktalarını D ile birleştirmeyen orta şerit yamuğun alanı kaç santimetrekaredir?', '9 cm²', ['6 santimetrekare', '8 santimetrekare', '12 santimetrekare'], 'Üç kenarortayın böldüğü 6 eş alandan biri olan GDC üçgeninin alanı 72 / 6 = 12 cm²\'dir. [GD] ve [GC] orta noktalarını birleştiren orta taban GDC\'den G köşesinde 12 / 4 = 3 cm² ayırır; geriye kalan yamuk şeridin alanı 12 - 3 = 9 cm² olur.'),
];
